(() => {
  window.textbookCourses = window.textbookCourses || {};
  window.textbookCourses.bashkortTele7 = [{"title":"Бүлек 1. ЯҢЫНАН МӘКТӘПКӘ. VI КЛАСТА ҮТЕЛГӘНДӘРҘЕ ҠАБАТЛАУ","tasks":[{"number":1,"key":"1-1","label":"Бүлек 1 · №1","question":"Ориентир по заголовку блока ответов: Һөйләмдәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һөйләмдәр:\nМинең мәктәбем ҙур һәм матур.\nКласта өҫтәл, ултырғыс, таҡта бар.\nУҡытыусы дәреслек менән эшләй.\nБөгөн матур көн.\nБеренсе сентябрь — Белем көнө.\nҠыңғырау дәрескә саҡыра.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":2,"key":"1-2","label":"Бүлек 1 · №2","question":"Ориентир по заголовку блока ответов: «Беренсе сентябрь — Белем көнө».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Беренсе сентябрь — Белем көнө».\nБеренсе сентябрь — Белем көнө. Был көндө уҡыусылар мәктәпкә килә.\nМинең мәктәбем матур. Класта өҫтәлдәр, ултырғыстар, таҡта бар.\nУҡытыусы беҙҙе ҡаршы ала. Ҡыңғырау шылтырай, дәрес башлана.\nБеҙ яңы уҡыу йылына шатланабыҙ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":3,"key":"1-3","label":"Бүлек 1 · №3","question":"Ориентир по заголовку блока ответов: «Мәктәпкә тәү барған көн».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Мәктәпкә тәү барған көн».\n1) Өлгө яуап:\nМин мәктәпкә тәү тапҡыр барған көндө яҡшы хәтерләйем. Көн йылы һәм\nсыуаҡ ине. Мин матур кейем кейҙем, ҡулыма портфель алдым. Мәктәптә\nуҡытыусым һәм класташтарым менән таныштым. Был көн минең өсөн бик\nбәхетле һәм онотолмаҫлыҡ булды.\n2) Терәк һүҙҙәр: беренсе сентябрь, сыуаҡ көн, мәктәп, портфель, уҡытыусы,\nкласташтар, ҡыңғырау, шатлыҡ, тәүге дәрес.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":4,"key":"1-4","label":"Бүлек 1 · №4","question":"Ориентир по заголовку блока ответов: Һорауҙарға яуап:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һорауҙарға яуап:\n1) Башҡорт телендә 12 һуҙынҡы һәм 28 тартынҡы өн бар.\n2) Башҡорт алфавитында 42 хәреф бар.\n3) Һуҙынҡы өндәр: а, ә, о, ө, у, ү, ы, э(е), и һәм һүҙҙәрҙә ҡулланылған\nоҙон/ҡыҫҡа варианттар.\n4) Омонимдар — әйтелеше һәм яҙылышы бер төрлө, мәғәнәләре төрлө һүҙҙәр:\nай — небесное тело; ай — месяц.\nСинонимдар — мәғәнәләре яҡын һүҙҙәр: матур — гүзәл.\nАнтонимдар — ҡапма-ҡаршы мәғәнәле һүҙҙәр: ҙур — бәләкәй.\n\n«Уҡытыусыма» шиғыры буйынса:\n1) Шағир һуҡмаҡты «алтын» тип атай, сөнки мәктәпкә һәм белемгә алып барған\nюл кеше тормошонда бик ҡәҙерле.\n2) «Алтын һуҡмаҡ» — белем юлы; «тормошом китабы» — кешенең тормош юлы.\n3) Уҡытыусы баланы белем донъяһына алып инә, уға төрлө ерҙәр, тәбиғәт,\nдонъя тураһында белем бирә.\n4) Өлгө: Минең уҡытыусым изгелекле, талапсан һәм белемле. Ул беҙгә\nяңы белем бирә, ярҙам итә һәм дөрөҫ юл күрһәтә.\n5) Ятлау — устно.\n6) Йырҙы өйрәнеү — устно.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":5,"key":"1-5","label":"Бүлек 1 · №5","question":"Ориентир по заголовку блока ответов: I. Көҙ билдәләре:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I. Көҙ билдәләре:\nел — көслө, һалҡын;\nкөн — һалҡын, болотло;\nямғыр — көслө, оҙайлы;\nяпраҡ — һары, ҡыҙыл.\nII. Синонимдар:\nшатланыу — ҡыуаныу, һөйөнөү;\nбарыу — китеү, атлау;\nйөрөү — гиҙеү, йөрөп сығыу;\nкүңелһеҙләнеү — ҡайғырыу, бойоғоу.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":6,"key":"1-6","label":"Бүлек 1 · №6","question":"Ориентир по заголовку блока ответов: Текст буйынса:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Текст буйынса:\nХлеб — икмәк.\nТруд — хеҙмәт.\nНарод — халыҡ.\n\nа) Һөйләмдәр:\nИкмәк — ҙур байлыҡ.\nХеҙмәт кешене биҙәй.\nБашҡорт халҡы хеҙмәт һөйә.\n\nб) Мәҡәлдәр:\nИкмәк — ил байлығы.\nХеҙмәт төбө — хөрмәт.\nХалыҡ әйтһә — хаҡ әйтер.\n\n2) Тәржемә:\nгосударство — дәүләт;\nпрочно — ныҡ, ныҡлы;\nпот — тир;\nусталость — арыу, талсығыу;\nкорень — тамыр.\n\n3) Профессиялар:\nуҡытыусы, табип, төҙөүсе, ашнаҡсы, һатыусы, инженер, водитель, игенсе,\nурмансы, рәссам.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":7,"key":"1-7","label":"Бүлек 1 · №7","question":"Ориентир по заголовку блока ответов: Сифат дәрәжәләре:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Сифат дәрәжәләре:\nҺары:\nтөп — һары;\nсағыштырыу — һарыраҡ;\nартыҡлыҡ — һап-һары;\nаҙһытыу — һарғылт.\nЙәшел:\nтөп — йәшел;\nсағыштырыу — йәшелерәк;\nартыҡлыҡ — йәм-йәшел;\nаҙһытыу — йәшкелт.\n\nҺөйләмдәр:\nКөҙ япраҡтар һары.\nБыл япраҡ тегеһенән һарыраҡ.\nУрманда һап-һары япраҡтар күп.\nАғастың япрағы йәшкелт төҫтә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":8,"key":"1-8","label":"Бүлек 1 · №8","question":"Ориентир по заголовку блока ответов: 1) Ҡотлау:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"1) Ҡотлау:\nЯңы уҡыу йылы менән! Һиңә яҡшы билдәләр, ныҡлы һаулыҡ, уңыштар һәм\nҡыҙыҡлы дәрестәр теләйем!\n2) Йәйге каникул тураһында өлгө:\nЙәйге каникулда мин өләсәйемдә ял иттем. Дуҫтарым менән футбол уйнаным,\nйөҙҙөм, урманға барҙым. Каникул бик күңелле үтте.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":9,"key":"1-9","label":"Бүлек 1 · №9","question":"Ориентир по заголовку блока ответов: «Тел — халыҡтың иң ҙур хазинаһы».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Тел — халыҡтың иң ҙур хазинаһы».\n1) Тел быуаттар буйына халыҡ менән бергә йәшәй, уның тарихын, мәҙәниәтен\nһәм рухын һаҡлай. Шуға күрә тел — халыҡтың ҙур хазинаһы.\n2) Туған тел кешеләрҙе берләштерә, быуындарҙы бәйләй, халыҡтың хәтерен һаҡлай.\n3) Ҡыҫҡа мәғлүмәт: башҡорт теле — башҡорт халҡының туған теле һәм Башҡортостан\nРеспубликаһының дәүләт телдәренең береһе.\n4) Бөйөк шәхестәрҙең тел тураһында һүҙҙәрен уҡытыусы биргән өҫтәмә сығанаҡтан\nяҙырға мөмкин. Сайт өсөн әҙер вариант: «Туған телде һаҡлау — халыҡтың рухи\nмираҫын һаҡлау».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":10,"key":"1-10","label":"Бүлек 1 · №10","question":"Ориентир по заголовку блока ответов: «Миҙгелдәр».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Миҙгелдәр».\n1) Яҙҙы — зәңгәр сирень, йәшел үлән;\nйәйҙе — аллы-гөллө сәскәләр, ҡоштар;\nкөҙҙө — ҡыҙыл, һары япраҡтар;\nҡышты — аҡ ҡар биҙәй.\n2) Таныш булмаған һүҙҙәрҙе һүҙлектән ҡарау — индивидуаль.\n3) Өҫтәмә: Яҙын ҡар ирей, йәйен көндәр йылы, көҙөн япраҡтар ҡойола,\nҡышын ерҙе аҡ ҡар ҡаплай.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":11,"key":"1-11","label":"Бүлек 1 · №11","question":"Ориентир по заголовку блока ответов: «В» өнө схемаһына миҫалдар:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«В» өнө схемаһына миҫалдар:\nрус һүҙҙәрендә: вагон, ваза, велосипед;\nҡалын ижекле һүҙҙәрҙә: ваҡыт, тауыш;\nнәҙек ижекле һүҙҙәрҙә: Вәсилә, тейен.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":12,"key":"1-12","label":"Бүлек 1 · №12","question":"Ориентир по заголовку блока ответов: Текст тураһында:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Текст тураһында:\nТекста кешенең туған телгә мөнәсәбәте тураһында һүҙ бара.\nМин автор менән килешәм. Төп фекер: туған илде яратыу туған телде яратыуҙан\nайырылғыһыҙ.\nТөп һөйләмдәр:\n«Тыуған илгә булған ысын мөхәббәтте әсә теленә ҡарата булған мөхәббәттән тыш\nкүҙ алдына килтереү мөмкинме һуң?»\n«Әсә теленә вайымһыҙ ҡараған кеше — ҡырағай кеше, зарарлы кеше».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":13,"key":"1-13","label":"Бүлек 1 · №13","question":"Ориентир по заголовку блока ответов: «Урман аптекаһында» — хикәйә:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Урман аптекаһында» — хикәйә:\nЙәй көнө беҙ лагерҙа ял иттек. Бер көндө «Шифалы үләндәр» китабын алып,\nурманға сыҡтыҡ. Беҙ үләндәрҙе йыйыу ҡағиҙәләрен өйрәндек. Ҡыҙыл китапҡа\nингән үҫемлектәрҙе өҙмәнек. Аҡланда юл япрағы, меңьяпраҡ, мәтрүшкә, аҡ сәскә\nйыйҙыҡ. Уларҙы киптерҙек, гербарий яһаныҡ. Һуңынан аптекала шифалы үләндәрҙең\nни өсөн файҙалы булыуын белдек. Тәбиғәтте һаҡлау — изге эш.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":14,"key":"1-14","label":"Бүлек 1 · №14","question":"Ориентир по заголовку блока ответов: Һынамыштар — яҙып алыу/диктант өсөн. Әҙер вариант:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һынамыштар — яҙып алыу/диктант өсөн. Әҙер вариант:\n«Ҡар япраҡтар ҡойолоп бөтмәҫ элек яуһа, тиҙ иреп бөтөр».\n«Имән сәтләүеге уңһа, ҡыш йылы килер, уңыш мул булыр».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":15,"key":"1-15","label":"Бүлек 1 · №15","question":"Ориентир по заголовку блока ответов: «Хушлашыу».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Хушлашыу».\nШиғыр «Хушлашыу» тип атала, сөнки көҙ көнө ҡоштар тыуған ер менән хушлашып,\nйылы яҡҡа осоп китә.\n1) Көҙ, ҡоштарҙың йылы яҡҡа китеүе тураһында.\n2) Һары япраҡлы урман, зәңгәр күк һәм осоп барған ҡоштар күҙ алдына баҫа.\n3) Ҡоштар яҙын кире ҡайтып, Ватанды тағы йырлап данлаһын тигән теләк һалынған.\n4) Көҙөн япраҡтар һарғая һәм ҡойола, көндәр ҡыҫҡара, һауа һалҡыная,\nҡоштар көньяҡҡа китә.\n5) Һүрәт — ижади эш.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":16,"key":"1-16","label":"Бүлек 1 · №16","question":"Ориентир по заголовку блока ответов: I. Диалогты дауам итеү:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I. Диалогты дауам итеү:\n— Һаумы, Әлфиә. Һине йәй буйы күрмәнем, һағынып бөттөм.\n— Сәләм, Гөлдәр. Ҡайһылай үҫеп, матурланып киткәнһең. Йә, Гөлдәр,\nһөйлә әле, һин нисек ял иттең?\n— Мин ауылда өләсәйемдә ял иттем. Йылғала йөҙҙөм, еләк йыйҙым.\n— Каникул оҡшанымы?\n— Эйе, бик оҡшаны. Ә һин нисек ял иттең?\n— Мин ҡала лагерына йөрөнөм.\n\nII. «Мәктәп китапханаһында»:\n— Һаумыһығыҙ. Миңә башҡорт халыҡ әкиәттәре китабы кәрәк ине.\n— Һаумы. Бына был китапты ҡара.\n— Уны ҡасан тапшырырға?\n— Ике аҙнанан.\n— Рәхмәт, һау булығыҙ.\n— Һау булығыҙ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":17,"key":"1-17","label":"Бүлек 1 · №17","question":"Ориентир по заголовку блока ответов: «Осенний день» — башҡортса ҡыҫҡа тәржемә:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Осенний день» — башҡортса ҡыҫҡа тәржемә:\nИртәнән ваҡ ямғыр яуа. Ул йәйге йәшенле ямғыр кеүек түгел, ә туҡтамайынса\nтыныс ҡына яуа. Ел ағас һәм үләндәрҙең өлгөргән орлоҡтарын алыҫҡа тарата.\nҠайын беренсе булып һарғая. Уҫаҡ ҡыҙыл, ҡуйы ҡыҙыл, алтын төҫлө япраҡтарға\nтөрөнә. Көҙгө ел ҡоро япраҡтарҙы өҙөп, еүеш ергә түшәй. Сәскәләр юҡҡа сыға.\nҠарағалар баҡсанан өйөр булып осоп килеп, түбәләргә ҡуна. Ҡояш һуңыраҡ сыға\nһәм иртәрәк байый.\nҠыҫҡаса: көҙгө көн һалҡын, ямғырлы, елле; тәбиғәт ҡышҡа әҙерләнә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":18,"key":"1-18","label":"Бүлек 1 · №18","question":"Ориентир по заголовку блока ответов: Йомаҡтар:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Йомаҡтар:\n1) Умарталыҡ/умарта.\n2) Һуған.\n3) Кәбеҫтә.\n4) Гранат (йәки күп орлоҡло емеш — контекст буйынса).\n5) Сөгөлдөр.\nӨҫтәмә йомаҡтар:\n«Йәйен һоро, ҡышын аҡ, уға шулай яҡшыраҡ». — Ҡуян.\n«Ҡыҙыл төймә таптым, ауыҙыма ҡаптым». — Еләк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":19,"key":"1-19","label":"Бүлек 1 · №19","question":"Ориентир по заголовку блока ответов: Башватҡыс:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Башватҡыс:\n1) ҡәләм;\n2) китап;\n3) ултырғыс;\n4) сәғәт;\n5) уҡытыусы;\n6) көндәлек;\n7) өҫтәл;\n8) таҡта.\nДауамы: дәреслек, дәфтәр, класс, ҡыңғырау, аҡбур.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":20,"key":"1-20","label":"Бүлек 1 · №20","question":"Ориентир по заголовку блока ответов: I. Ятлау өсөн:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I. Ятлау өсөн:\n«Китап — белем шишмәһе».\n«Күп уҡыһаң, күп белерһең».\n\nII. Рус мәҡәлдәренә башҡортса мәғәнәләш варианттар:\n1) Что посеешь, то и пожнешь. — Ни сәсһәң, шуны урырһың.\n2) Куй железо, пока горячо. — Тимерҙе ҡыҙыуында һуҡ.\n3) Кончил дело, гуляй смело. — Эш бөткәс, уйнарға ярай.\n4) Кто не работает, тот не ест. — Кем эшләмәй, шул ашамай.\n5) У страха глаза велики. — Ҡурҡҡанға ҡуш күренә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":21,"key":"1-21","label":"Бүлек 1 · №21","question":"Ориентир по заголовку блока ответов: I. Һүҙбәйләнештәрҙе тәржемә итеү:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I. Һүҙбәйләнештәрҙе тәржемә итеү:\nтуған мәктәбем — моя родная школа;\nалтын һуҡмаҡ — золотая тропинка;\nфәндәр тауы — гора знаний/наук;\nалтын көҙ — золотая осень;\nтәүге көн — первый день;\nнурҙар һибә — рассыпает лучи;\nйәйге ял — летний отдых;\nосоп киттеләр — улетели;\nхәйерле юл — счастливого пути;\nшаулап үҫ — расти пышно/быстро;\nшау-гөр килеп — шумно, оживлённо.\n\nII. Текст:\n«Минең мәктәбем»\nМинең туған мәктәбем матур. Тәүге көндө беҙгә ҡояш нурҙар һибә.\nМәктәптә беҙ фәндәр тауына күтәреләбеҙ. Уҡытыусылар беҙгә хәйерле юл\nтеләй. Мин мәктәбемде яратам.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":22,"key":"1-22","label":"Бүлек 1 · №22","question":"Ориентир по заголовку блока ответов: Өфө музейҙары тураһында:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Өфө музейҙары тураһында:\nӨфөлә Милли музей, М. В. Нестеров исемендәге дәүләт художество музейы,\nархеология музейы, Халыҡтар дуҫлығы музейы, Мәжит Ғафуриҙың мемориаль\nйорт-музейы, С. Т. Аксаковтың йорт-музейы һәм башҡа музейҙар бар.\nИң боронғо һәм ҙур музей — Башҡортостан Республикаһының Милли музейы.\nНестеров музейында рус һәм башҡорт рәссамдарының картиналары һаҡлана.\n1) Өлгө: Мин Милли музейҙа һәм Нестеров музейында булдым.\n2) Миңә тарихи экспонаттар һәм рәссамдарҙың картиналары хәтерҙә ҡалды.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":23,"key":"1-23","label":"Бүлек 1 · №23","question":"Ориентир по заголовку блока ответов: Ситуациялар:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Ситуациялар:\n1) Дуҫҡа:\n«Өфөлә күп музейҙар бар. Иң ҙурҙарының береһе — Милли музей.\nНестеров музейында рус һәм башҡорт рәссамдарының картиналары бар».\n2) Һорауҙар:\n«Милли музейға нисек барырға?»\n«Музей сәғәт нисәлә асыла?»\n«Салауат Юлаев һәйкәле ҡайҙа?»\n«Нестеров музейына нисек барып була?»\n3) Электрон хат:\n«Мин һиңә Мостай Кәрим тураһында яҙам. Ул Башҡортостандың халыҡ шағиры,\nКеләш ауылында тыуған, Бөйөк Ватан һуғышында ҡатнашҡан. Уның\n“Оҙон-оҙаҡ бала саҡ”, “Беҙҙең өйҙөң йәме”, “Өс таған” әҫәрҙәре билдәле».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]}]},{"title":"Бүлек 2. АУЫЛ ТОРМОШО","tasks":[{"number":1,"key":"2-1","label":"Бүлек 2 · №1","question":"Ориентир по заголовку блока ответов: Икмәк кешелектең ҙур мөғжизәһе, сөнки ул кешенең йәшәүе өсөн төп аҙыҡ,","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Икмәк кешелектең ҙур мөғжизәһе, сөнки ул кешенең йәшәүе өсөн төп аҙыҡ,\nә уны үҫтереү күп хеҙмәт һәм белем талап итә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":2,"key":"2-2","label":"Бүлек 2 · №2","question":"Ориентир по заголовку блока ответов: Төп фекер: икмәк табынға килгәнсе бик оҙон һәм ауыр хеҙмәт юлы үтә.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Төп фекер: икмәк табынға килгәнсе бик оҙон һәм ауыр хеҙмәт юлы үтә.\nТексты шартлы рәүештә 4 өлөшкә бүлергә мөмкин:\n1) Ерҙе әҙерләү һәм сәсеү.\n2) Баҫыуҙы тәрбиәләү һәм уңыш йыйыу.\n3) Игенде таҙартыу һәм онға әйләндереү.\n4) Икмәк бешереү.\nҺорауҙар:\n— Иген үҫтереү өсөн ерҙе нисек әҙерләйҙәр?\n— Уңышты ниндәй машиналар менән йыялар?\n— Ашлыҡ он булғансы күпме операция үтә?\n— Ни өсөн икмәкте ҡәҙерләргә кәрәк?\nМәҡәлдәр:\n«Икмәк — ил байлығы».\n«Икмәк ҡәҙерен ас белер».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":3,"key":"2-3","label":"Бүлек 2 · №3","question":"Ориентир по заголовку блока ответов: «Алтын башаҡтар».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Алтын башаҡтар».\nӘкиәт шулай атала, сөнки ысын «алтын» — хеҙмәт менән үҫтерелгән бойҙай\nбөртөктәре.\n1) Төп фекер: хеҙмәт кешене туйындыра һәм үҙаллы итә. Әкиәт кешеләрҙе\nэшләргә, тир түгеп йәшәргә өйрәтә.\n2) «Ең һыҙғанып, тир сығарып эшләү» — ялҡауланмайынса, тырышып эшләү.\n3) Һорауҙар:\n— Әсәнең нисә улы булған?\n— Улдары нимә һораған?\n— Әсә «алтын»ды ҡайҙан эҙләргә ҡушҡан?\n— Егеттәр ниндәй эш башҡарған?\n— Ысын алтын нимә булып сыҡҡан?\n4) Фәһем: ололарҙы хөрмәт итергә, кеселәргә ярҙам итергә, хеҙмәттән ҡурҡмаҫҡа.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":4,"key":"2-4","label":"Бүлек 2 · №4","question":"Ориентир по заголовку блока ответов: I. Икмәк юлы:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I. Икмәк юлы:\nорлоҡ — семена;\nбашаҡ — колос;\nиген — хлеб/зерно;\nер — земля;\nтрактор — трактор;\nһөрөү — пахать;\nйомшартыу — рыхлить;\nон — мука;\nикмәк — хлеб;\nбойҙай — пшеница;\nбешереү — печь;\nкомбайн — комбайн;\nйыйыу — собирать;\nэлеватор — элеватор;\nелләтеү — проветривать/веять.\nХикәйә: Орлоҡто ергә сәсәләр. Трактор менән ерҙе һөрәләр һәм йомшарталар.\nБойҙай үҫеп, башаҡлана. Комбайн уңышты йыя. Игенде элеваторға илтеп\nтаҙарталар, киптерәләр. Унан он тарттыралар һәм икмәк бешерәләр.\nII. «Мул уңышлы» — уңышы күп, бай уңыш тигәнде аңлата.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":5,"key":"2-5","label":"Бүлек 2 · №5","question":"Ориентир по заголовку блока ответов: I.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I.\n1) Икмәк бешереү өсөн он, һыу, әсетке, тоҙ кәрәк.\n2) Милли ҡамыр аштары: бәлеш, бауырһаҡ, ҡоймаҡ, бишбармаҡҡа һалма,\nҡуллама, ҡыҫтыбый.\n3) Мәҫәлән, рус халҡында — блины, пироги; татар халҡында — өсбосмаҡ,\nсәк-сәк; үзбәк халҡында — самса.\nII.\n1) Көҙ — уңыш йыйыу, һалҡынайыу, япраҡтар һарғайыу миҙгеле.\n2) «Алтын көҙ» — ағастар һәм япраҡтар һары-алтын төҫкә ингән осор.\n3) Һары, ҡыҙыл, көрән, йәшел, күк төҫтәр ҡулланыр инем.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":6,"key":"2-6","label":"Бүлек 2 · №6","question":"Ориентир по заголовку блока ответов: «Көҙ уртаһы».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Көҙ уртаһы».\nТема: октябрҙәге тәбиғәт үҙгәрештәре.\nТөп фекер: көҙ уртаһында тәбиғәт һәм кешеләр ҡышҡа әҙерләнә.\nПлан:\n1) Октябрь һауалары.\n2) Ҡоштар һәм хайуандар.\n3) Урмансылар эше.\n4) Баҡсасылар эше.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":7,"key":"2-7","label":"Бүлек 2 · №7","question":"Ориентир по заголовку блока ответов: Текст менән эш өсөн өлгө:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Текст менән эш өсөн өлгө:\nТекстың темаһы — көҙгө тәбиғәт.\nТөп фекер — көҙ һәр тереклек ҡышҡа әҙерләнә.\nТекст бәйләнешле, абзацтарға бүленгән, уның башы, төп өлөшө һәм йомғағы бар.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":8,"key":"2-8","label":"Бүлек 2 · №8","question":"Ориентир по заголовку блока ответов: Тәбиғәтте һаҡлау тураһында:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Тәбиғәтте һаҡлау тураһында:\nТәбиғәтте һаҡлау — ағас ултыртыу, сүп ташламау, йылғаларҙы бысратмау,\nҡоштарҙы һәм йәнлектәрҙе һаҡлау, урманда ут менән һаҡ булыу.\nӨлгө һөйләм: «Беҙҙең класс яҙ һайын мәктәп ихатаһында ағастар ултырта».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":9,"key":"2-9","label":"Бүлек 2 · №9","question":"Ориентир по заголовку блока ответов: Мәҡәлдәрҙе күсереп яҙыу — уҡытыусы талап иткәнсә.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Мәҡәлдәрҙе күсереп яҙыу — уҡытыусы талап иткәнсә.\nТиповой аңлатма: хеҙмәт, ер, икмәк һәм тырышлыҡ тураһында мәҡәлдәр кешене\nэшһөйәр булырға өйрәтә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":10,"key":"2-10","label":"Бүлек 2 · №10","question":"Ориентир по заголовку блока ответов: I. Оҡшаш яҙылышлы һүҙҙәр: был күнегеүҙә рус һәм башҡорт һүҙҙәренең","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I. Оҡшаш яҙылышлы һүҙҙәр: был күнегеүҙә рус һәм башҡорт һүҙҙәренең\nәйтелеш-яҙылыш үҙенсәлеге сағыштырыла.\nII. Шиғырҙың фекере:\nТәбиғәттең һәр өлөшө үҙенең биҙәге менән матур, ә кеше лә тыуған ерен\nматурлау өсөн изге эштәр башҡарырға тейеш.\nҺуңғы ике юл: «Тыуып үҫкән ерҙәрҙе гөл итеү» — тыуған яҡты төҙөкләндереү,\nағас ултыртыу, таҙалыҡ һаҡлау, кешеләргә файҙа килтереү.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":11,"key":"2-11","label":"Бүлек 2 · №11","question":"Ориентир по заголовку блока ответов: I. Төшөп ҡалған хәрефтәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I. Төшөп ҡалған хәрефтәр:\n«Тәбиғәтте һаҡлау — бөтә кешенең бурысы. Ошо маҡсат менән урмандарҙы\nиҫәпһеҙ ҡырҡыу, йылға һәм күлдәрҙә ау менән балыҡ тотоу, урмандарҙа\nҡош-ҡортҡа һәм кейеккә һунар итеү тыйыла. Йәш ағастар ултыртыр өсөн\nсаралар күреү — кешеләрҙең бурысы. Бындай эштәрҙә уҡыусыларҙың да\nҡатнашыуы мотлаҡ».\n1) Өлгө: Беҙ ағастар ултыртабыҙ, өмәләрҙә ҡатнашабыҙ, сүп-сар йыябыҙ.\n2) Һорау: «Урманды нисек һаҡларға?», «Йылғаларҙы бысраныуҙан нисек ҡотҡарырға?»\n3) Тәбиғәт — беҙҙең уртаҡ байлығыбыҙ.\nII. Өҫтәмә фекер: тәбиғәтһеҙ кеше йәшәй алмай, шуға уны һаҡлау һәр кешенең\nбурысылыр.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":12,"key":"2-12","label":"Бүлек 2 · №12","question":"Ориентир по заголовку блока ответов: Проект «Башҡортостан тәбиғәте»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Проект «Башҡортостан тәбиғәте»:\n1) Башҡортостандың географик урыны.\n2) Урал тауҙары.\n3) Ағиҙел, Ҡариҙел, Дим, Йүрүҙән йылғалары.\n4) Урмандар һәм үҫемлектәр.\n5) Йәнлектәр.\n6) Шүлгәнташ, милли парктар, тәбиғәт ҡомартҡылары.\n7) Тәбиғәтте һаҡлау.\nЙомғаҡ: Башҡортостан тәбиғәте бай һәм матур, уны киләсәк быуындар өсөн\nһаҡларға кәрәк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":13,"key":"2-13","label":"Бүлек 2 · №13","question":"Ориентир по заголовку блока ответов: Текстың исеме: «Тыуған тупраҡ».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Текстың исеме: «Тыуған тупраҡ».\nТөп фекер: тыуған ер кешегә көс, ышаныс һәм рухи таяныс бирә.\nДауам: «Мин тыуған еремә ҡайтҡас, бер семтем тупраҡты йортобоҙ эргәһенә\nһалдым. Әсәйемдең һүҙҙәрен тағы иҫкә төшөрҙөм. Тыуған ерҙе һаҡлау —\nһәр кешенең бурысы».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":14,"key":"2-14","label":"Бүлек 2 · №14","question":"Ориентир по заголовку блока ответов: Дөрөҫ вариант:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Дөрөҫ вариант:\n«Урман — беҙҙең милли байлығыбыҙ, ғорурлығыбыҙ. Башҡортостандың 40 процент\nсамаһы ере урман менән ҡапланған. Шулай ҙа ул төпһөҙ байлыҡ түгел.\nУрмандарҙың яртыһы ҡырҡып бөтөрөлгән. Шуға ла бөгөн ағас ултыртыу —\nбеҙҙең бурыс».\nҺөйләмдәр:\nУрман — ҙур байлыҡ.\nЕрҙе һаҡларға кәрәк.\nТәбиғәтте һаҡлау — беҙҙең бурыс.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":15,"key":"2-15","label":"Бүлек 2 · №15","question":"Ориентир по заголовку блока ответов: Диалог буйынса:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Диалог буйынса:\n1) «Бесән өҫтө» — бесән сабыу һәм йыйыу ваҡыты. Ул йәйҙең ҡоро, йылы\nкөндәрендә үтә.\n2) Мәҡәл: «Хеҙмәт төбө — хөрмәт». «Эшләгән ашар, эшләмәгән ҡарап ҡалыр».\n3) Ҡылымдар: китеп бараһың — хәҙерге заман; алып барам — хәҙерге;\nсабам — хәҙерге; өйрәтте — үткән; өйрәтер — киләсәк; ярҙам итермен —\nкиләсәк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":16,"key":"2-16","label":"Бүлек 2 · №16","question":"Ориентир по заголовку блока ответов: Төп фекер:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Төп фекер:\nБал ҡорто тырыш булған кеүек, кеше лә эшһөйәр һәм белемле булырға тейеш.\nИң мөһим юл: «Балы булмаған кәрәҙҙең, белемһеҙ ҡалған кешенең бер файҙаһы юҡ».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":17,"key":"2-17","label":"Бүлек 2 · №17","question":"Ориентир по заголовку блока ответов: Һүрәттәр буйынса хикәйә — өлгө:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һүрәттәр буйынса хикәйә — өлгө:\n«Ауылдағы бер көн».\nИртән ауыл кешеләре эшкә тотона. Берәүҙәр мал ҡарай, икенселәр баҡсала\nэшләй. Балалар өлкәндәргә ярҙам итә. Көндөҙ бесән сабалар, һыу ташыйҙар,\nмалдарҙы ашаталар. Кисен ғаилә бергә ял итә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":18,"key":"2-18","label":"Бүлек 2 · №18","question":"Ориентир по заголовку блока ответов: «Тыуған яҡ».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Тыуған яҡ».\nМинең тыуған яғым бик матур. Унда бейек тауҙар, урмандар, күлдәр һәм\nйылғалар бар. Урманда төрлө ҡоштар һайрай, сәскәләр һәм үләндәр үҫә.\nСаф һауа, тыуған тупраҡ миңә бик ҡәҙерле. Тыуған ерҙе яратырға һәм\nтәбиғәтте һаҡларға кәрәк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":19,"key":"2-19","label":"Бүлек 2 · №19","question":"Ориентир по заголовку блока ответов: «Бал ҡорто».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Бал ҡорто».\nБал ҡорто кешегә бал бирә. Бал составында организм өсөн кәрәкле күп\nфайҙалы матдәләр бар. Ул дауалауҙа ла ҡулланыла.\n1) Башҡорт балы тәме һәм сифаты менән билдәле; умартасылыҡ Башҡортостанда\nборондан үҫешкән.\n2) Һүрәт — ижади эш.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":20,"key":"2-20","label":"Бүлек 2 · №20","question":"Ориентир по заголовку блока ответов: «Кто прав?» — яуап:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Кто прав?» — яуап:\nИльгиз да, Ильдар ҙа хаҡ түгел. Урманда тере ҡыуаҡтарҙы ла, ағастарҙы ла\nутын өсөн ҡырҡырға ярамай; усаҡ өсөн ҡороған ботаҡтарҙы ғына йыйырға кәрәк.\n1) Тематик һүҙҙәр: август — август; йылға — река; урман — лес; балан —\nкалина; миләш — рябина; усаҡ — костёр; ҡоро утын — сухие дрова;\nҡыуаҡ — куст; ҡайын — берёза.\n2) Ролдәргә бүлеү — устно.\n3) Йөкмәтке: Ильгиз менән Ильдар ялда усаҡ яғырға теләй. Берәү ҡыуаҡты,\nикенсеһе ҡайынды ҡырҡырға тәҡдим итә. Аталары икеһенең дә хаҡ булмауын аңлата.\n4) Мин улар урынында ҡоро ботаҡтар йыйыр инем.\n5) Атаһы урманда тере ағастарҙы һәм ҡыуаҡтарҙы ҡырҡырға ярамауын,\nтәбиғәтте һаҡларға кәрәклеген аңлатҡан.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]}]},{"title":"Бүлек 3. БАШҠОРТОСТАН БУЙЛАП СӘЙӘХӘТ","tasks":[{"number":1,"key":"3-1","label":"Бүлек 3 · №1","question":"Ориентир по заголовку блока ответов: Һөйләмдәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һөйләмдәр:\n1) Башҡортостан — беҙҙең гүзәл тыуған еребеҙ.\n2) Уның тәбиғәте матур, иҫ киткес.\n3) Беҙ ата-бабалар төйәген яратабыҙ.\n4) Тырыш хеҙмәт менән Тыуған илебеҙҙе ҡыуандырырбыҙ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":2,"key":"3-2","label":"Бүлек 3 · №2","question":"Ориентир по заголовку блока ответов: «Урал» халыҡ йыры:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Урал» халыҡ йыры:\n1) Төп фекер: Урал — ата-бабаларҙың изге төйәге, уны һаҡлау өсөн батырҙар\nғүмерен биргән; Тыуған илде яратыу — оло ҡиммәт.\n2) Талдарҙы ҡырҡҡанда тамған һут батырҙарҙың ҡаны менән сағыштырыла.\n3) Батырҙар: Салауат Юлаев, Ҡаһым түрә, Шайморатов һәм башҡалар.\nСалауат Юлаев — башҡорт халҡының милли батыры, шағир, Пугачёв\nихтилалында ҡатнашҡан.\n4) Урал батыр тураһында төп легенда — «Урал батыр» эпосы; унда Урал батыр\nхалыҡты һәм тәбиғәтте яҡлай.\n5) Ятлау — устно.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":3,"key":"3-3","label":"Бүлек 3 · №3","question":"Ориентир по заголовку блока ответов: Яңғыҙлыҡ исемдәр менән һөйләмдәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Яңғыҙлыҡ исемдәр менән һөйләмдәр:\nАғиҙел йылғаһы Башҡортостан буйлап аға.\nМин Өфө ҡалаһында уҡыйым.\nЯмантау — Башҡортостандағы бейек тауҙарҙың береһе.\nМин Башҡортостан менән ғорурланам.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":4,"key":"3-4","label":"Бүлек 3 · №4","question":"Ориентир по заголовку блока ответов: «Аҡбуҙат», «Аманат»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Аҡбуҙат», «Аманат»:\nӨлгө: Был журналдар балалар һәм үҫмерҙәр өсөн сыға. Унда әҙәби әҫәрҙәр,\nтарих, тәбиғәт, ижад, фән һәм уҡыусылар тормошо тураһында материалдар баҫыла.\nМини-мәҡәлә: «Минең мәктәбемдә спорт яраталар. Уҡыусылар ярыштарҙа ҡатнаша,\nеңеүҙәр яулай. Спорт беҙҙе көслө һәм берҙәм итә».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":5,"key":"3-5","label":"Бүлек 3 · №5","question":"Ориентир по заголовку блока ответов: Яҙылыш:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Яҙылыш:\nБашҡортостан Республикаһы;\nӨфө;\nСалауат Юлаев;\nскульптор Сосланбәк Тавасиев;\nЯмантау;\nИрәмәл;\nЙоматау;\nЯнғантау;\nКрасноусол;\nЯҡтыкүл;\nШафран;\nЧехов.\n1) Карта менән эш — устно.\n2) Диалогты дауам итеү:\n— Башҡортостандың иң ҙур йылғаһы нисек атала?\n— Ағиҙел.\n— Республикала ниндәй тауҙар бар?\n— Ямантау, Ирәмәл һәм башҡа тауҙар бар.\n— Башҡортостан нимә менән дан тота?\n— Урал тауҙары, бал, нефть, урмандар һәм матур тәбиғәт менән.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":6,"key":"3-6","label":"Бүлек 3 · №6","question":"Ориентир по заголовку блока ответов: Урам атамаларын алфавит буйынса — шәхси задание.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Урам атамаларын алфавит буйынса — шәхси задание.\nӨлгө: Ленин урамы, Пушкин урамы, Салауат Юлаев проспекты, Совет урамы.\n\n«Урал йөрәге»:\n1) Устно.\n2) Башҡортостан Уралдың йөрәгендә урынлашҡан, шуға шиғыр шулай атала.\n3) Шағир Тыуған илде, Башҡортостанды, Ағиҙелде яратыуын әйтә.\n4) Яттан яҙыу — устно/письменно.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":7,"key":"3-7","label":"Бүлек 3 · №7","question":"Ориентир по заголовку блока ответов: I. Төп фекер:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I. Төп фекер:\nИлен яратҡан, белемле, бай рухлы, үҙ халҡын ҡәҙерләгән кешеләр генә\nилде үҫтерә ала.\n1) Бай рухлы шәхестәр — белемле, намыҫлы, илһөйәр, ихтирамлы кешеләр.\nМиҫал: Мостай Кәрим, Рәми Ғарипов.\n2) Автор йәштәргә белемле, ҙур шәхес булып үҫергә һәм илен яратырға саҡыра.\nII.\n1) «Һандуғас» һүҙенән: һан, дан, уғас, һауа (хәрефтәрҙе ҡулланыу мөмкинлегенә ҡарап).\n2) Тышҡы ҡиәфәт: оҙон, ҡыҫҡа, матур, бөҙрә сәсле, ҡара күҙле, оҙон буйлы.\n3) Эске сифаттар: аҡыллы, әҙәпле, тырыш, ярҙамсыл, намыҫлы, ихтирамлы.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":8,"key":"3-8","label":"Бүлек 3 · №8","question":"Ориентир по заголовку блока ответов: «Урал имәне» — төшөп ҡалған хәрефтәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Урал имәне» — төшөп ҡалған хәрефтәр:\nБашҡорт халҡы борон-борондан Уралда йәшәй. Ул ошо ерҙә имән кеүек тамырланған.\nҠайындар ҙа, йүкәләр ҙә үҫә янында. Ләкин еребеҙҙең төп ағасы — Урал имәне!\nБашҡа халыҡтарҙыҡы кеүек үк, башҡорт халҡының да төп терәге — ғәзиз ере.\nХалыҡ үҙ ерендә генә ирекле. Башҡорт халҡы үҙенең бөтә тарихында азатлыҡ өсөн\nкөрәшкән. Азатлыҡ юҡ икән, ил дә юҡ!\nБәхет бит был: илебеҙ бар, ул — Башҡортостан. Бәхет бит был: дәүләтебеҙ бар,\nул — республикабыҙ! Үҙебеҙҙең яҙмыш үҙебеҙҙең ҡулыбыҙҙа тигән һүҙ был.\n\n1) [Типовой ответ, не процитирован в самом тексте]: флагтағы күк төҫ —\nсафлыҡ һәм изге ниәт; аҡ — тыныслыҡ һәм асыҡлыҡ; йәшел — ирек һәм тормош.\n2) [Типовой ответ]: герб авторы — Фазлетдин Ислахов.\n3) Суверенитет республикаға үҙ дәүләт символдарын, үҙидара һәм үҙаллылыҡтың\nмөһим хоҡуҡтарын бирҙе.\n4) Яңғыҙлыҡ исемдәр: Урал, Башҡорт/Башҡортостан, Башҡортостан Республикаһы.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":9,"key":"3-9","label":"Бүлек 3 · №9","question":"Ориентир по заголовку блока ответов: Һүҙбәйләнештәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һүҙбәйләнештәр:\nйырла — йырлап торған ҡыҙ, йырлап йөрөгән бала;\nкөл — көлөп торған уҡыусы, көлөп һөйләгән малай;\nуҡы — уҡып ултырған ҡыҙ, уҡып килгән уҡыусы;\nһөйлә — һөйләп торған уҡытыусы, һөйләп барған кеше;\nбейе — бейеп йөрөгән ҡыҙ, бейеп торған балалар;\nһикер — һикереп уйнаған бала, һикереп төшкән малай;\nуйла — уйлап ултырған уҡыусы, уйлап һөйләгән кеше.\nҺөйләмдәр:\nЙырлап торған ҡыҙҙың тауышы матур.\nУҡып ултырған уҡыусы һорауға яуап бирҙе.\nБейеп йөрөгән балалар байрамды йәмләне.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":10,"key":"3-10","label":"Бүлек 3 · №10","question":"Ориентир по заголовку блока ответов: Текст:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Текст:\n1) Авторҙың тыуған илгә мөнәсәбәте — яратыу, ғорурланыу, һоҡланыу.\n2) Башҡортостан бай һәм гүзәл ил: унда нефть, металл, иген, мал, ҡаялар,\nдалалар, йылғалар һәм күлдәр бар.\n3) Дауам: «Беҙ республикабыҙҙың байлығын һаҡларға, тәбиғәтен ҡәҙерләргә\nһәм тырыш хеҙмәт менән уны тағы ла матур итергә тейешбеҙ».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":11,"key":"3-11","label":"Бүлек 3 · №11","question":"Ориентир по заголовку блока ответов: Һөнәрҙәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һөнәрҙәр:\n1) Эйе, һөнәрҙәр бик күп.\n2) Урмансы урманды һаҡлай, ағастар ултырта, янғындан һәм законһыҙ\nҡырҡыуҙан һаҡлауҙа ҡатнаша.\n3) Өлгө: Мин табип һөнәрен иң кәрәклеләрҙең береһе тип уйлайым,\nсөнки табип кешеләрҙең һаулығын һаҡлай.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":12,"key":"3-12","label":"Бүлек 3 · №12","question":"Ориентир по заголовку блока ответов: «Арҡайым»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Арҡайым»:\n1) Беҙҙең эраға тиклем XVII–XVI быуаттар, бронза быуаты. Ағас һәм балсыҡтан.\n2) Түңәрәк планлы, нығытмалары, йорттары, майҙаны һәм металл иретеү мейестәре\nбулған боронғо ҡаласыҡ.\n3) «Металл ҡойоусының бер көнө»:\nИртән оҫта мейесте ҡыҙҙырған. Ул руданы әҙерләп, металды иретеүгә тотонған.\nЭҫе мейес янында оҙаҡ эшләгән. Әҙер металлдан кәрәкле әйберҙәр яһалған.\nКисен эште тамамлап, ғаиләһе янына ҡайтҡан.\n4) Текста сәбәп аңлатылмай. Фараз: янғын, һуғыш, тәбиғәт шарттарының үҙгәреүе\nйәки башҡа хәүеф арҡаһында киткәндәр.\n5) Өҫтәмә мәғлүмәт талап итә.\n6) Шәхси яуап.\n7) План:\n1) Арҡайымдың табылыуы.\n2) Ҡаласыҡтың төҙөлөшө.\n3) Халыҡтың көнкүреше һәм һөнәрҙәре.\n4) Арҡайым серҙәре.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":13,"key":"3-13","label":"Бүлек 3 · №13","question":"Ориентир по заголовку блока ответов: Тәржемә:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Тәржемә:\nтыуған ер — родная земля;\nтәбиғәт — природа;\nборонғо ҡала — древний город;\nхалыҡ — народ;\nтыныс тормош — мирная жизнь;\nбыуат — век;\nата-бабалар — предки;\nбыуындан быуынға — из поколения в поколение.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":14,"key":"3-14","label":"Бүлек 3 · №14","question":"Ориентир по заголовку блока ответов: Л. Н. Толстой тураһында:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Л. Н. Толстой тураһында:\n[Өҫтәмә мәғлүмәт талап иткән задание.]\nУчебниктағы нигеҙ: Л. Н. Толстой Башҡортостанда ҡымыҙ менән дауаланған,\nбашҡорттарҙың тормошон күҙәткән. Картина буйынса: яҙыусы башҡорт далаһында,\nурындағы кешеләр араһында һүрәтләнгән.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":15,"key":"3-15","label":"Бүлек 3 · №15","question":"Ориентир по заголовку блока ответов: «Тыуған ил»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Тыуған ил»:\nТөп фекер: Тыуған ил кеше өсөн иң кәрәкле һәм ҡәҙерле төшөнсә; ул өйҙән,\nғаиләнән, мәктәптән, ҡала/райондан һәм республиканан башлана.\nТәржемә (ҡыҫҡаса): Родина начинается с самого человека, его дома, родителей,\nбабушки и дедушки, друзей, школы, города/района и республики. Как птице нужно\nнебо, рыбе — река, траве — земля, так человеку нужна Родина.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":16,"key":"3-16","label":"Бүлек 3 · №16","question":"Ориентир по заголовку блока ответов: Бәйләнешле текст:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Бәйләнешле текст:\nБашҡортостан — минең тыуған ерем. Уның тәбиғәте иҫ киткес матур.\nАғиҙел һәм Ҡариҙел йылғалары, Урал тауҙары — беҙҙең ғорурлыҡ.\nРеспубликабыҙҙа боронғо ҡалалар, ҡәлғәләр һәм тәбиғәт һәйкәлдәре бар.\nМин Тыуған илемде ҡәҙерләйем һәм уны һаҡларға теләйем.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":17,"key":"3-17","label":"Бүлек 3 · №17","question":"Ориентир по заголовку блока ответов: Шиғырҙың мәғәнәһе:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Шиғырҙың мәғәнәһе:\nЛирик герой Уралды шул тиклем ярата, хатта ҡолон булып уның киңлегендә\nйүгерергә, йәш ҡурай булып моңға ҡушылырға теләй. Төп хис — Тыуған ергә\nкөслө һөйөү.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":18,"key":"3-18","label":"Бүлек 3 · №18","question":"Ориентир по заголовку блока ответов: Заһир Исмәғилев:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Заһир Исмәғилев:\nТәржемә һәм һөйләү өсөн:\nЗаһир Исмәғилев Белорет районы Сермен ауылында тыуған. Ул Башҡорт дәүләт\nдрама театрында актёр булып эшләй, Мәскәү консерваторияһында уҡый.\nБашҡортостан Композиторҙар союзы рәйесе, Өфө сәнғәт институты ректоры була.\nУның йырҙары башҡорт музыкаһының алтын фондына инә.\n1) Ошо текст буйынса һөйләү.\n2) Өҫтәмә мәғлүмәт — уҡытыусы/сығанаҡ менән тултырырға.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":19,"key":"3-19","label":"Бүлек 3 · №19","question":"Ориентир по заголовку блока ответов: Проект «Тыуған ерем — Башҡортостан»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Проект «Тыуған ерем — Башҡортостан»:\n1) Республика тураһында ҡыҫҡаса.\n2) Дәүләт символдары.\n3) Урал тауҙары һәм йылғалар.\n4) Тәбиғәт байлыҡтары.\n5) Мәҙәниәт, әҙәбиәт, музыка.\n6) Танылған кешеләр.\n7) Йомғаҡ: «Башҡортостан — минең ғорурлығым».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":20,"key":"3-20","label":"Бүлек 3 · №20","question":"Ориентир по заголовку блока ответов: Музыка ҡоралдары:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Музыка ҡоралдары:\nбарабан — һуғыу;\nскрипка — тартыу;\nфлейта — уйнау;\nҡумыҙ — сиртеү;\nгармун — уйнау;\nҡурай — уйнау;\nдумбыра — сиртеү;\nборғо — уйнау.\nҺөйләмдәр:\nМин ҡурайҙа уйнарға өйрәнәм.\nМузыкант скрипкала матур итеп уйнай.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]}]},{"title":"Бүлек 4. СПОРТ. СПОРТ КӘРӘК-ЯРАҠТАРЫ","tasks":[{"number":1,"key":"4-1","label":"Бүлек 4 · №1","question":"Ориентир по заголовку блока ответов: Текст буйынса:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Текст буйынса:\n1) Эйе, спорт менән шөғөлләнеү һаулыҡты нығыта. Өлгө: мин йөҙөүҙе,\nфутболды һәм еңел атлетиканы яратам.\n2) Учебникта һуңыраҡ телгә алынған билдәле Башҡортостан спортсылары:\nАндрей Черкасов, Галина Куклева, Александр Батталов, Людмила Матвеева,\nҒабдрахман Ҡадыров.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":2,"key":"4-2","label":"Бүлек 4 · №2","question":"Ориентир по заголовку блока ответов: «Беҙҙең ғаилә — ярышта»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Беҙҙең ғаилә — ярышта»:\n1) Текст буйынса бер-берегеҙгә һорауҙар:\n— Ярышта кемдәр ҡатнаша?\n— Ғаилә ағзалары ниндәй күнекмәләр башҡара?\n— Ярыштың маҡсаты нимәлә?\n2) План:\n1. Ярышҡа әҙерлек.\n2. Ғаиләләрҙең сығышы.\n3. Спорт күнекмәләре.\n4. Еңеүселәр һәм яҡшы кәйеф.\n3) Өлгө: Беҙҙең мәктәптә эстафета, футбол, волейбол, саңғы, йүгереү\nһәм «Күңелле старттар» ярыштары үткәрелә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":3,"key":"4-3","label":"Бүлек 4 · №3","question":"Ориентир по заголовку блока ответов: Диалогтарҙы дауам итеү:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Диалогтарҙы дауам итеү:\n1)\n— Мин йөҙөү секцияһына яҙылырға килдем.\n— Һиңә нисә йәш?\n— Ун өс.\n— Йөҙә беләһеңме?\n— Эйе, беләм, ләкин яҡшыраҡ өйрәнергә теләйем.\n— Яҡшы, күнекмәләргә кил.\n\n2)\n— Марат, һин хоккейға беренсе кластан алып йөрөйһөң.\n— Эйе, миңә хоккей бик оҡшай.\n— Күнекмәләр ауырмы?\n— Ауыр, ләкин ҡыҙыҡ. Хоккей көслө һәм етеҙ булырға өйрәтә.\n\n3)\n— Сания, «Һаулығың — байлығың» тигән сығышты әйҙә бергә әҙерләйек.\n— Ярай. Мин спорт һәм дөрөҫ туҡланыу тураһында материал табам.\n— Ә мин иртәнге зарядка һәм көн тәртибе тураһында яҙам.\n— Һуңынан сығышты бергә уҡып тикшерербеҙ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":4,"key":"4-4","label":"Бүлек 4 · №4","question":"Ориентир по заголовку блока ответов: Һүҙбәйләнештәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һүҙбәйләнештәр:\nюл буйлап барыу; кино ҡарау; аҡса йыйыу; ҡунаҡҡа барыу;\nваҡытында килеү; спорт менән шөғөлләнеү; түңәрәккә йөрөү.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":5,"key":"4-5","label":"Бүлек 4 · №5","question":"Ориентир по заголовку блока ответов: Төп фекер:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Төп фекер:\nКеше өсөн иң ҙур бәхеттәрҙең береһе — һаулыҡ. Һаулыҡты һаҡлау өсөн\nдөрөҫ туҡланырға, спорт менән шөғөлләнергә, көн тәртибен үтәргә,\nял һәм хеҙмәтте дөрөҫ ойошторорға, зарарлы ғәҙәттәрҙән баш тартырға кәрәк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":6,"key":"4-6","label":"Бүлек 4 · №6","question":"Ориентир по заголовку блока ответов: 13–15 йәштә организмда үҙгәрештәр бара. Шуға:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"13–15 йәштә организмда үҙгәрештәр бара. Шуға:\n— табип кәңәшен тыңларға;\n— спорт менән ойошҡан рәүештә шөғөлләнергә;\n— иртәнге зарядка яһарға;\n— йоҡо, ял һәм туҡланыу режимын һаҡларға кәрәк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":7,"key":"4-7","label":"Бүлек 4 · №7","question":"Ориентир по заголовку блока ответов: Мәҡәлдәрҙең мәғәнәһе:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Мәҡәлдәрҙең мәғәнәһе:\n«Һаулығың — байлығың» — һаулыҡ аҡсанан да ҡәҙерлерәк.\n«Байлыҡ башы — һаулыҡ» — һәр эш өсөн тәү сиратта һаулыҡ кәрәк.\n«Һаҡланған — һаулыҡҡа туйған» — үҙен һаҡлаған кеше сирҙе иҫкәртә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":8,"key":"4-8","label":"Бүлек 4 · №8","question":"Ориентир по заголовку блока ответов: Тәржемә:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Тәржемә:\nбоксерские перчатки — бокс бирсәткәләре;\nгантели — гантелдәр;\nочки — күҙлек;\nклюшка — клюшка;\nкожаный мяч — күн туп;\nочко — мәрәй;\nспортивная форма — спорт формаһы;\nворота — ҡапҡа.\n\nҺөйләмдәр:\nБоксер бокс бирсәткәләре кейә.\nХоккейсы ҡулына клюшка ала.\nФутболда тупты ҡапҡаға индерергә тырышалар.\nСпортсы күнекмәлә гантелдәр ҡуллана.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":9,"key":"4-9","label":"Бүлек 4 · №9","question":"Ориентир по заголовку блока ответов: Хоккейсының формаһы:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Хоккейсының формаһы:\nХоккейсы шлем, һаҡлағыс кейем, бирсәткә, коньки кейә. Ҡулында клюшка була.\nФорма уны шайбанан, бәрелешеүҙән һәм йығылыуҙан һаҡлай.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":10,"key":"4-10","label":"Бүлек 4 · №10","question":"Ориентир по заголовку блока ответов: Шиғырҙы ятлау — устно.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Шиғырҙы ятлау — устно.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":11,"key":"4-11","label":"Бүлек 4 · №11","question":"Ориентир по заголовку блока ответов: Диалог:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Диалог:\n— Ял көнө нимә эшләйбеҙ?\n— Әйҙә, катокка барайыҡ.\n— Ярай. Конькиҙарың бармы?\n— Бар. Һинеке юҡ икән, прокаттан алырбыҙ.\n— Бик яҡшы. Сәғәт икелә осрашайыҡ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":12,"key":"4-12","label":"Бүлек 4 · №12","question":"Ориентир по заголовку блока ответов: «Марат» тексында һүҙҙәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Марат» тексында һүҙҙәр:\nЭлек әсәһе эшләй торған эштәрҙе хәҙер инде Марат үҙе шәп башҡара.\nКөн дә иртәнсәк бүлмәһен елләтә, йоҡо урынын, бөтә өйҙө йыйыштыра,\nкөсө еткән эштәрҙә әсәһенә ярҙам итә.\n1) Марат бүлмәһен елләтә, йоҡо урынын һәм өйҙө йыйыштыра, әсәһенә ярҙам итә.\n2) Ул үҙаллыланған, тәртиплерәк һәм эшһөйәрерәк булған.\n3) Өлгө: ул үҙенең ғаилә алдындағы бурыстарын аңлай башлаған.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":13,"key":"4-13","label":"Бүлек 4 · №13","question":"Ориентир по заголовку блока ответов: Диалогтағы спорт темаһы:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Диалогтағы спорт темаһы:\nИшембай ҡалаһы шахмат һәм шашка буйынса чемпиондар тәрбиәләгән.\nУчебниктың башҡа текстарында Ғабдрахман Ҡадыров, Галина Куклева,\nАндрей Черкасов, Александр Батталов, Людмила Матвеева телгә алына.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":14,"key":"4-14","label":"Бүлек 4 · №14","question":"Ориентир по заголовку блока ответов: Һүҙҙәрҙе дөрөҫ уҡыу — устно.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һүҙҙәрҙе дөрөҫ уҡыу — устно.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":15,"key":"4-15","label":"Бүлек 4 · №15","question":"Ориентир по заголовку блока ответов: «Футбол».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Футбол».\nФутбол уйнау һаулыҡ өсөн файҙалы: ул тиҙлекте, көстө, иғтибарҙы,\nҡыйыулыҡты, арауыҡта йүнәлеш табыуҙы үҫтерә. Командала уйнау\nдуҫлыҡҡа, тәртипкә һәм бер-береңә ярҙам итергә өйрәтә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":16,"key":"4-16","label":"Бүлек 4 · №16","question":"Ориентир по заголовку блока ответов: Уйын — практик/устно.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Уйын — практик/устно.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":17,"key":"4-17","label":"Бүлек 4 · №17","question":"Ориентир по заголовку блока ответов: Т. Яблонскаяның «Иртә» картинаһы буйынса инша.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Т. Яблонскаяның «Иртә» картинаһы буйынса инша.\n\nПлан:\n1) Иртәнге бүлмә.\n2) Ҡыҙҙың күнегеүе.\n3) Ҡояшлы кәйеф.\n4) Картинаның тәьҫире.\n\nИнша:\nКартинала иртәнге яҡты бүлмә һүрәтләнгән. Төп урында йәш ҡыҙ тора.\nУл йоҡонан торғандан һуң иртәнге гимнастика яһай. Ҡыҙҙың хәрәкәттәре\nирекле, кәйефе күтәренке. Тәҙрәнән бүлмәгә йылы ҡояш нурҙары төшә.\nБүлмә таҙа һәм йыйнаҡ, унда өҫтәл, ултырғыс һәм көндәлек тормошҡа\nкәрәкле әйберҙәр бар. Рәссам асыҡ һәм йылы төҫтәр ҡулланып, сафлыҡ,\nматурлыҡ һәм йәшлек тойғоһо тыуҙырған. Картина миңә сәләмәт һәм\nтәртипле тормош тураһында уйлата.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":18,"key":"4-18","label":"Бүлек 4 · №18","question":"Ориентир по заголовку блока ответов: Тәржемә:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Тәржемә:\nйөҙөү — плавание;\nсаңғыла йөрөү — ходьба/катание на лыжах;\nспартакиада үткәреү — проводить спартакиаду;\nярыш ойоштороу — организовать соревнование;\nҡотлауҙар — поздравления;\nеңеүсе — победитель;\nкүнекмәләр — тренировки/упражнения;\nтөҙ атыу — метко стрелять;\nмәргәнлектә ярышыу — соревноваться в меткости;\nтрамплиндан һикереү — прыжок с трамплина;\nоҙонлоҡҡа һикереү — прыжок в длину;\nбейеклеккә һикереү — прыжок в высоту;\nмилли көрәш — национальная борьба;\nтаҫтамал — полотенце;\nат сабыштары — скачки;\nарҡаға һалыу — положить на спину;\nматур фигуралар яһау — выполнять красивые фигуры;\nетеҙлек — ловкость/быстрота.\n\n5 һөйләм:\nМин йөҙөү менән шөғөлләнәм.\nМәктәптә ярыш ойошторолдо.\nЕңеүсегә ҡотлауҙар әйттеләр.\nҺабантуйҙа милли көрәш үткәрелә.\nАт сабыштары күп тамашасы йыя.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":19,"key":"4-19","label":"Бүлек 4 · №19","question":"Ориентир по заголовку блока ответов: Ваҡиғаларҙың дөрөҫ тәртибе:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Ваҡиғаларҙың дөрөҫ тәртибе:\n1) Салт аяҙ эҫе көн.\n2) Илдар күлгә һыу инергә йыйынды.\n3) Күрше йортҡа офицер һәм уның улы килде.\n4) Илдар малай менән танышырға һәм осоусы булырға өйрәнергә теләне.\n5) Шуға күрә ул һыу инергә барманы һәм малайҙың уйнарға сыҡҡанын көттө.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":20,"key":"4-20","label":"Бүлек 4 · №20","question":"Ориентир по заголовку блока ответов: «Милли уйындар».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Милли уйындар».\n1) Көс, йылғырлыҡ һәм күнекмәләрҙә оҫталығы булған кешеләр абруйлы булған.\n2) Милли уйындар организмды сыныҡтыра, берҙәмлек тойғоһо тәрбиәләй,\nкешене шәхес итеп үҫтерә.\n3) Күп уйындар ат менән бәйле.\n4) Тексттағы һүҙҙәр:\nкөс — сила; йылғырлыҡ — ловкость; оҫталыҡ — мастерство;\nабруйлы — авторитетный; ихтирамлы — уважаемый;\nберҙәмлек — единство; бәйге — состязание; сослоҡ — проворство.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":21,"key":"4-21","label":"Бүлек 4 · №21","question":"Ориентир по заголовку блока ответов: «Иппотерапия»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Иппотерапия»:\nБөгөн медицинала «иппотерапия» тигән төшөнсә бар:\nбыл кеше күңелен, эске донъяһын ат менән аралашыу аша дауалау икән.\nӘ башҡорт халҡында был дауалау быуаттар төпкөлөнән килә,\nтимәк, ат менән дуҫ булған кеше «ҡара күңелле» була алмай.\n\n1) Иппотерапия — ат менән аралашыу һәм һыбай йөрөү аша кешенең физик\nһәм психологик хәлен яҡшыртыу ысулы.\n2) Учебниктағы фекер буйынса, башҡорт аты халыҡ тормошонда бик мөһим булған;\nат менән бәйле уйындар, бәйгеләр һәм һыбай йөрөү традицияһы борондан килгән.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":22,"key":"4-22","label":"Бүлек 4 · №22","question":"Ориентир по заголовку блока ответов: Проект «Һаулыҡ — ҙур байлыҡ»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Проект «Һаулыҡ — ҙур байлыҡ»:\n1) Һаулыҡ нимә ул?\n2) Көн тәртибе.\n3) Дөрөҫ туҡланыу.\n4) Спорт һәм зарядка.\n5) Йоҡо һәм ял.\n6) Зарарлы ғәҙәттәрҙән баш тартыу.\n7) Йомғаҡ: һаулыҡты сирләгәндән һуң түгел, алдан һаҡларға кәрәк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":23,"key":"4-23","label":"Бүлек 4 · №23","question":"Ориентир по заголовку блока ответов: 1) Н. А. Добролюбов һабантуйҙы боронғо гректарҙың Олимпия уйындары менән сағыштыра.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"1) Н. А. Добролюбов һабантуйҙы боронғо гректарҙың Олимпия уйындары менән сағыштыра.\n2) Өлгө: һабантуй һәм милли уйындар тураһында Р. Әйүповтың тексын һәм\nбашҡорт халыҡ ижады материалдарын ҡулланырға мөмкин.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":24,"key":"4-24","label":"Бүлек 4 · №24","question":"Ориентир по заголовку блока ответов: Ҡотлау:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Ҡотлау:\n«Тыуған көнөң менән! Һиңә ныҡлы һаулыҡ, бәхет, уҡыуҙа уңыштар,\nяҡшы дуҫтар һәм күтәренке кәйеф теләйем. Һәр ваҡыт алсаҡ һәм аҡыллы булып ҡал!»","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":25,"key":"4-25","label":"Бүлек 4 · №25","question":"Ориентир по заголовку блока ответов: Ҡышҡы урман.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Ҡышҡы урман.\nа) Айыу менән терпе өңдәрендә йоҡлай.\nб) Төлкө менән бүре аҙыҡ эҙләп урман һәм ҡырҙарҙа йөрөй.\nв) Ҡуянды аҡ төҫө, оҙон ҡолағы, үткер күҙе һәм йүгерек аяғы һаҡлай.\nг) Мышы ағас ҡайыры ашай, үлән һәм мүк соҡоп таба.\nғ) Ҡор менән һуйыр ҡар аҫтында йәшеренә; ҡыҙылтүш һәм ҡарабаш турғайҙар\nкеше йәшәгән урындарға яҡынлаша; тумыртҡа көн буйы аҙыҡ эҙләй.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":26,"key":"4-26","label":"Бүлек 4 · №26","question":"Ориентир по заголовку блока ответов: Һөйләмдәрҙе дөрөҫ тәртиптә:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һөйләмдәрҙе дөрөҫ тәртиптә:\n1) Башҡортостан — спорт һөйөүселәр иле.\n2) Шуға күрә һәр ҡалала, ауылда ғаилә старттары, спартакиадалар,\nхалыҡ уйындары, төрлө ярыштар үткәрелә.\n3) Бындай спартакиадаларға күп халыҡ йыйыла.\n4) Тимәк, киләсәктә лә Башҡортостанды данлаған донъя чемпиондары буласаҡ!\n5) Улар араһында һеҙҙең уҡыусылар ҙа булһын!","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":27,"key":"4-27","label":"Бүлек 4 · №27","question":"Ориентир по заголовку блока ответов: «Башҡортостан ҡалаларында спорт»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Башҡортостан ҡалаларында спорт»:\nСалауат — саңғы һәм йөҙөү.\nБелорет — тау саңғыһы.\nБөрө — уҡ атыу.\nМәләүез — ат спорты («Толпар» ипподромы).\nИшембай — шахмат һәм шашка.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":28,"key":"4-28","label":"Бүлек 4 · №28","question":"Ориентир по заголовку блока ответов: Яңы йыл:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Яңы йыл:\n1) Өлгө: Мин яңы йылға спорт кәрәк-ярағы йәки китап алырға теләр инем.\n2) «Яңы йыл менән! Һаулыҡ, бәхет, уңыш һәм тыныслыҡ теләйем!»\n3) Өлгө: класты биҙәнек, шыршы ҡуйҙыҡ, йыр һәм шиғырҙар әҙерләнек.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":29,"key":"4-29","label":"Бүлек 4 · №29","question":"Ориентир по заголовку блока ответов: «Башҡортостан — чемпиондар иле».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Башҡортостан — чемпиондар иле».\nҺорауҙар һәм яуаптар:\n— Андрей Черкасов кем? — Европа һәм донъя чемпионы тенниссы.\n— Галина Куклева кем? — Биатлон буйынса донъя чемпионы.\n— Александр Батталов ниндәй спортсы? — Көрәшсе, ике тапҡыр донъя еңеүсеһе.\n— Людмила Матвеева ниндәй спорт төрөндә танылған? — Еңел атлетикала.\n— Ғабдрахман Ҡадыров нисә тапҡыр донъя чемпионы булған? — Алты тапҡыр.\n— Ул ниндәй спорт төрөндә сығыш яһаған? — Боҙ өҫтөндә мотоцикл ярыштарында.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":30,"key":"4-30","label":"Бүлек 4 · №30","question":"Ориентир по заголовку блока ответов: Һүҙҙәр буйынса бәйләнешле текст:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һүҙҙәр буйынса бәйләнешле текст:\nСпортта еңеү өсөн тырышлыҡ һәм даими күнекмәләр кәрәк. Ярышта еңеүсе булыу\nеңел түгел: спортсы ауырлыҡтарҙы һәм ҡыйынлыҡтарҙы еңә. Иртәнге зарядка,\nкөрәш, йүгереү, йөҙөү һәм башҡа күнекмәләр һаулыҡты нығыта. Милли көрәш\nһәм ат сабыштары Башҡортостанда киң таралған. Спорт — дөйөм үҫеш һәм\nсәләмәт тормош өсөн мөһим.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":31,"key":"4-31","label":"Бүлек 4 · №31","question":"Ориентир по заголовку блока ответов: «Яңы йылда»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Яңы йылда»:\nЗал уртаһында ҡуйы шыршы тора. Ул туҡтауһыҙ әйләнә, тирә-яҡты нурландыра.\nШыршыны балалар уратып алған. Улар йырлайҙар, бейейҙәр, шиғыр һөйләйҙәр,\nтөрлө уйындар уйнайҙар. Бында Ҡыш бабай ҙа килгән. Уға Ҡарһылыу ҙа эйәргән.\nУлар беҙҙе Яңы йыл менән ҡотланы.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":32,"key":"4-32","label":"Бүлек 4 · №32","question":"Ориентир по заголовку блока ответов: Башҡортостанда йылғалар, күлдәр, шишмәләр күп.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Башҡортостанда йылғалар, күлдәр, шишмәләр күп.\nБашҡортостандың иң ҙур йылғаһы — Ағиҙел.\nУл Ирәмәл тауы һырттарынан башлана, Кама йылғаһына ҡоя.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":33,"key":"4-33","label":"Бүлек 4 · №33","question":"Ориентир по заголовку блока ответов: Ребус:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Ребус:\nӘҘ ҺӨЙЛӘ, КҮП ЭШЛӘ.\n\nАңлатма: ребус «кәрәҙ → әҙ», «һөйәк → һөй + л», «мәк → ә»,\n«күркә → кү + п», «эшләпә → эшлә» өлөштәренән йыйыла.\n\nРеспубликалағы ҙур күлдәр тураһында:\nАсылыкүл — Башҡортостандағы иң ҙур күлдәрҙең береһе һәм иң ҙур тәбиғи күл.\nҠандракүл дә республиканың иң ҙур һәм билдәле күлдәре иҫәбенә инә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":34,"key":"4-34","label":"Бүлек 4 · №34","question":"Ориентир по заголовку блока ответов: I.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I.\nСәләмәт тәндә — сәләмәт рух, ти халыҡ. Һаулыҡты ҡайтанан булдырыуға\nҡарағанда, ауырыуҙы иҫкәртеү күпкә отошлораҡ. Спорт менән даими шөғөлләнеү,\nайыҡ тормош алып барыу — һаулыҡ нигеҙе.\nДонъяла уртаса кеше ғүмере яҡынса 64 йәш менән билдәләнә.\nЯпония кешеләре иң оҙон ғүмерлеләрҙән һанала.\nЯпондар майҙы аҙ ҡулланалар, балыҡты күп ашайҙар.\nМәҡәл: «Сәләмәт тәндә — сәләмәт рух».\n\nII.\nУлар иң бейеккә менә, иң шәп йүгерә, иң мәргән ата,\nиң ауырҙы күтәрә, иң көслөнө еңә.\nАҡса, донъя малы артынан ҡыуып, иң ҙур байлыҡты — һаулыҡты оноторға ярамай.\nМәҡәл: «Байлыҡтың алды — тән һаулығы».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":35,"key":"4-35","label":"Бүлек 4 · №35","question":"Ориентир по заголовку блока ответов: Диалог — учебникта башҡортса тәржемәһе әҙер бирелгән; ролләп уҡыу.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Диалог — учебникта башҡортса тәржемәһе әҙер бирелгән; ролләп уҡыу.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":36,"key":"4-36","label":"Бүлек 4 · №36","question":"Ориентир по заголовку блока ответов: Проект «Спорт — ул һаулыҡ»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Проект «Спорт — ул һаулыҡ»:\n1) Спорттың кеше өсөн файҙаһы.\n2) Иртәнге зарядка.\n3) Спорт төрҙәре.\n4) Башҡортостан спортсылары.\n5) Милли уйындар.\n6) Үҙем яратҡан спорт төрө.\n7) Йомғаҡ: спорт сәләмәт, көслө һәм тәртипле булырға ярҙам итә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":37,"key":"4-37","label":"Бүлек 4 · №37","question":"Ориентир по заголовку блока ответов: Яңы йыл шиғырындағы хистәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Яңы йыл шиғырындағы хистәр:\nАвтор иҫке йыл менән хушлашыуҙы һәм яңы йылды ҡаршылауҙы бергә кисерә:\nул берсә моңая, берсә шатлана. Өлгө: мин дә үткән йылды иҫкә төшөрәм,\nяңы йылдан яҡшы үҙгәрештәр көтәм һәм шатлыҡ тоям.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]}]},{"title":"Бүлек 5. МИН ҺӘМ БЕҘҘЕҢ ҒАИЛӘ","tasks":[{"number":1,"key":"5-1","label":"Бүлек 5 · №1","question":"Ориентир по заголовку блока ответов: Шиғыр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Шиғыр:\n1) Ер әсәй менән тиңләнә, сөнки ул да бөтә тереклеккә йәшәү бирә, һаҡлай һәм туйындыра.\n2) Шиғырҙа ҡыш миҙгеле һүрәтләнә: аҡ ҡар, һалҡын һәм ҡышҡы тәбиғәт күренештәре.\nТөп фекер: тәбиғәт тә, әсә лә кешегә йәшәү һәм йылылыҡ бирә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":2,"key":"5-2","label":"Бүлек 5 · №2","question":"Ориентир по заголовку блока ответов: «Әсә һүҙе»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Әсә һүҙе»:\n1) Әсә балаһының һау-сәләмәт, аҡыллы, бәхетле булып үҫеүен теләй.\n2) «Бәпес күрә барыу» йолаһына теләктәр:\n«Һау-сәләмәт үҫһен!»\n«Ата-әсәһенә иш булып үҫһен!»\n«Бәхетле һәм изгелекле бала булһын!»\n3) Ҡылымдар: үҫһен, тулып, торһон, ялтырап, алған, булһын.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":3,"key":"5-3","label":"Бүлек 5 · №3","question":"Ориентир по заголовку блока ответов: Ҡылымдарға рәүештәр өҫтәп:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Ҡылымдарға рәүештәр өҫтәп:\nӘлфиә оҙаҡ йоҡларға ятманы.\nРамаҙан матур итеп һөйләне.\nБалалар тиҙ йүгерҙеләр.\nӘсәй яй ғына йылмайҙы.\nМин иғтибар менән тыңланым.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":4,"key":"5-4","label":"Бүлек 5 · №4","question":"Ориентир по заголовку блока ответов: Фәһемле һүҙҙәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Фәһемле һүҙҙәр:\nМәғәнәһе: белемле булыу өсөн китапты, уҡытыусыны һәм хеҙмәтте хөрмәт итергә кәрәк.\nЯтлау өсөн ҡыҫҡа вариант:\n«Үҙемдә булған бөтә яҡшылыҡтарым өсөн китаптарға бурыслы».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":5,"key":"5-5","label":"Бүлек 5 · №5","question":"Ориентир по заголовку блока ответов: Һүҙҙәрҙе төркөмләү:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һүҙҙәрҙе төркөмләү:\nҒаилә/туғанлыҡ һүҙҙәре: әсәй, атай, ағай, апай, һеңле, ҡусты, өләсәй, олатай.\nКеше сифаттары: аҡыллы, наҙлы, тәртипле, шәфҡәтле, һиҙгер.\nАҙыҡ-түлек һүҙҙәре: икмәк, һөт, май, ит, емеш һәм башҡалар.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":6,"key":"5-6","label":"Бүлек 5 · №6","question":"Ориентир по заголовку блока ответов: Мәҡәлдәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Мәҡәлдәр:\n1) Ағасты япраҡ биҙәй, кешене хеҙмәт биҙәй.\n2) Алтын бөртөкләп йыйыла.\n3) Ҡалған эшкә ҡар яуа.\n4) Ете ҡат үлсә, бер ҡат киҫ.\n5) Аҡыллыға ым да етә.\n6) Ялҡауҙың көн дә башы ауырта.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":7,"key":"5-7","label":"Бүлек 5 · №7","question":"Ориентир по заголовку блока ответов: «Ҡошҡа әйләнгән әбей».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Ҡошҡа әйләнгән әбей».\n1) Әкиәттең йөкмәткеһе: әсәй ауырый, ә балалары уның хәлен ваҡытында аңламай\nһәм тейешле ярҙам күрһәтмәй. Әсә, ҡайғыһынан, ҡошҡа әйләнеп осоп китә.\n2) Ул балаларының битарафлығынан һәм хәстәрһеҙлегенән ҡошҡа әйләнә.\n3) Әкиәт әсәне ваҡытында ҡәҙерләргә кәрәклеген аңлата; ул ҡыҙғаныу һәм үкенеү хисе уята.\n4) Оҡшаш әкиәт итеп әсәне, ата-әсәне хөрмәтләү тураһындағы халыҡ әкиәттәрен әйтергә мөмкин.\n5) Төп фекер: «Әсәне ваҡытында ҡәҙерләргә кәрәк».\n6) Әкиәттәге ваҡиғаларҙың күпселеге үткән заманда һөйләнелә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":8,"key":"5-8","label":"Бүлек 5 · №8","question":"Ориентир по заголовку блока ответов: Шиғырҙы ятлау — устно.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Шиғырҙы ятлау — устно.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":9,"key":"5-9","label":"Бүлек 5 · №9","question":"Ориентир по заголовку блока ответов: Тәржемә:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Тәржемә:\nБашҡортостан — Башкортостан;\nВатан — Родина;\nҡомартҡы — реликвия/памятник;\nшәжәрә — родословная;\nтуған — родственник/родной;\nғәзиз — дорогой;\nихтирам — уважение.\n\n5 һөйләм:\nБашҡортостан — минең тыуған республикам.\nВатан һәр кешегә ҡәҙерле.\nШәжәрә ғаилә тарихын һаҡлай.\nБоронғо ҡомартҡыларҙы һаҡларға кәрәк.\nМин туғандарымды ихтирам итәм.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":10,"key":"5-10","label":"Бүлек 5 · №10","question":"Ориентир по заголовку блока ответов: «Дуҫым, серҙәшем».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Дуҫым, серҙәшем».\nТөп фекер: әсәй — баланың иң яҡын дуҫы һәм серҙәше.\nӨлгө яуап: Мин әсәйемә ышанам, сөнки ул һәр ваҡыт тыңлай, аңлай һәм ярҙам итә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":11,"key":"5-11","label":"Бүлек 5 · №11","question":"Ориентир по заголовку блока ответов: «Ярдамсы» картинаһы буйынса:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Ярдамсы» картинаһы буйынса:\nКартинала бала өйҙә өлкәндәргә ярҙам итә. Ул эште ихлас башҡара.\nБүлмә йыйнаҡ, көнкүреш әйберҙәре күренә. Картина ғаиләлә хеҙмәтте бүлешеү,\nата-әсәгә ярҙам итеү һәм тәртипле булыу тураһында һөйләй.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":12,"key":"5-12","label":"Бүлек 5 · №12","question":"Ориентир по заголовку блока ответов: Диалогтың башҡортса варианты:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Диалогтың башҡортса варианты:\n— Ғәфү итегеҙ, китап киоскы ҡайҙа?\n— Музей янында.\n— Унда нисек барырға?\n— Тура барығыҙ ҙа, музей эргәһендә уңға боролоғоҙ.\n— Рәхмәт.\n— Рәхим итегеҙ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":13,"key":"5-13","label":"Бүлек 5 · №13","question":"Ориентир по заголовку блока ответов: Атай һәм бала тураһында:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Атай һәм бала тураһында:\n1) Һуңғы һөйләм һорау билдәһе менән тамамлана, сөнки автор уҡыусыны:\n«Бала ла атаһына иғтибар һәм ярҙам күрһәтергә тейеш түгелме?» — тип уйланырға саҡыра.\n2) Дауам: Бала атаһының хеҙмәтен аңларға, уны хөрмәт итергә, хәлен белергә һәм\nкөсө еткәнсә ярҙам итергә тейеш.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":14,"key":"5-14","label":"Бүлек 5 · №14","question":"Ориентир по заголовку блока ответов: Шәжәрә:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Шәжәрә:\nШәжәрә — нәҫел-ырыуҙың, ғаиләнең быуындар буйынса тарихын күрһәткән родословная.\nАғас образы:\nтамырҙар — ата-бабалар һәм үткән;\nолоно — бөгөнгө быуын;\nботаҡтар — балалар һәм киләсәк быуындар.\n\nӨлгө:\nОлатай + өләсәй\n      ↓\nатай + әсәй\n      ↓\nмин, ағай/апай/һеңле/ҡусты.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":15,"key":"5-15","label":"Бүлек 5 · №15","question":"Ориентир по заголовку блока ответов: Өйҙәге эштәрем:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Өйҙәге эштәрем:\nМин бүлмәмде йыйыштырам, өҫтәлде әҙерләргә ярҙам итәм, һауыт-һаба йыуам,\nсүпте сығарам һәм кесе туғандарыма ярҙам итәм.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":16,"key":"5-16","label":"Бүлек 5 · №16","question":"Ориентир по заголовку блока ответов: Һүҙ уйыны — класта практик эш.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һүҙ уйыны — класта практик эш.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":17,"key":"5-17","label":"Бүлек 5 · №17","question":"Ориентир по заголовку блока ответов: «Атай кәңәше».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Атай кәңәше».\n1) Шиғыр атайҙың балаһына тормош тураһында кәңәштәр биреүе өсөн шулай атала.\n2) Төп фекер: кеше үҙ аҡылы менән уйларға, үҙ көсөнә ышанырға, тырыш һәм намыҫлы булырға тейеш.\n3) Мин һәр эштә үҙеңә ышанырға, ләкин аҡыллы кәңәште лә тыңларға кәрәклеген аңланым.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":18,"key":"5-18","label":"Бүлек 5 · №18","question":"Ориентир по заголовку блока ответов: Туғанлыҡ һүҙҙәре:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Туғанлыҡ һүҙҙәре:\nөләсәй — бабушка;\nолатай — дедушка;\nағай — старший брат/дядя;\nапай — старшая сестра/тётя;\nһеңле — младшая сестра;\nҡусты — младший брат;\nул — сын;\nҡыҙ — дочь;\nейән — внук;\nейәнсәр — внучка;\nир — муж/мужчина;\nҡатын — жена/женщина.\n\nАйырып бирелгән туғанлыҡ һүҙҙәре:\nеңгә — жена старшего брата/сноха;\nеҙнә — муж старшей сестры;\nкилен — невестка;\nкейәү — зять;\nҡәйнеш — младший брат мужа/жены (родственное обращение по системе родства);\nҡоҙа — сват;\nҡоҙағый — сваха;\nбалдыҙ — младшая сестра жены;\nҡайны — свёкор/тесть;\nҡәйнә — свекровь/тёща;\nҡайынбикә — старшая сестра супруга/супруги.\n\nҺөйләмдәр:\nМин өләсәйемә ҡунаҡҡа барҙым.\nАғайым университетта уҡый.\nЕңгәбеҙ беҙҙе байрам менән ҡотланы.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":19,"key":"5-19","label":"Бүлек 5 · №19","question":"Ориентир по заголовку блока ответов: Таһирҙың байрамы:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Таһирҙың байрамы:\n1) Эйе, уға күңелле булыр, сөнки туғандары һәм дуҫтары уны ҡотлай.\n2) Открытка:\n«Ҡәҙерле Сәғит! Тыуған көнөң менән! Һиңә ныҡлы һаулыҡ, бәхет,\nуҡыуҙа уңыштар һәм тоғро дуҫтар теләйем!»","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":20,"key":"5-20","label":"Бүлек 5 · №20","question":"Ориентир по заголовку блока ответов: Диалогтарға өлгө:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Диалогтарға өлгө:\n1)\n— Ләйсән, дәрестәрҙе эшләп бөткәс, әйҙә киноға барайыҡ.\n— Ярай, ләкин башта әсәйемә ярҙам итәм.\n— Сәғәт алтыла осрашайыҡмы?\n— Ярай.\n\n2)\n— Алло! Был Ғәлимовтар фатирымы?\n— Эйе.\n— Ринатты телефонға саҡырырға мөмкинме?\n— Хәҙер саҡырырмын.\n— Рәхмәт.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":21,"key":"5-21","label":"Бүлек 5 · №21","question":"Ориентир по заголовку блока ответов: Башҡорт теле түңәрәге — диалог:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Башҡорт теле түңәрәге — диалог:\n— Һин башҡорт теле түңәрәгенә йөрөйһөңмө?\n— Эйе, йөрөйөм.\n— Унда нимә эшләйһегеҙ?\n— Текстар уҡыйбыҙ, һөйләшергә өйрәнәбеҙ, йырҙар һәм шиғырҙар өйрәнәбеҙ.\n— Түңәрәк оҡшаймы?\n— Эйе, бик оҡшай.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":22,"key":"5-22","label":"Бүлек 5 · №22","question":"Ориентир по заголовку блока ответов: Автобиография өлгөһө:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Автобиография өлгөһө:\nМин, __________________, ______ йылда __________________ ҡалаһында/ауылында тыуҙым.\nХәҙер ______ мәктәбенең 7-се класында уҡыйым. Ғаиләмдә __________________ бар.\nМин __________________ менән ҡыҙыҡһынам. Буш ваҡытта __________________ яратам.\nКиләсәктә __________________ булырға теләйем.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":23,"key":"5-23","label":"Бүлек 5 · №23","question":"Ориентир по заголовку блока ответов: «Матур көн» — ятлау/яттан яҙыу.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Матур көн» — ятлау/яттан яҙыу.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":24,"key":"5-24","label":"Бүлек 5 · №24","question":"Ориентир по заголовку блока ответов: Текстың дөрөҫ тәртибе:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Текстың дөрөҫ тәртибе:\n1) Бала боҙҙа бәләгә осрай.\n2) Ул ауырый, дауалана.\n3) Дуҫтары уның янына килеп, дәрестәр буйынса ярҙам итә.\nТөп фекер: ысын дуҫтар ауыр ваҡытта ярҙам итә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":25,"key":"5-25","label":"Бүлек 5 · №25","question":"Ориентир по заголовку блока ответов: Әсәй тураһында:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Әсәй тураһында:\nТөп фекер — әсәйҙең мөхәббәте кеше күңелендә һәр саҡ йәшәй.\n«Һәр саҡ күңелеңдә йәшәй» — әсәйҙең тәрбиәһе, һүҙҙәре һәм һөйөүе\nкеше менән ғүмер буйы ҡала тигәнде аңлата.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":26,"key":"5-26","label":"Бүлек 5 · №26","question":"Ориентир по заголовку блока ответов: Ф. Исмәғилевтең «Йылға буйында» картинаһы буйынса инша:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Ф. Исмәғилевтең «Йылға буйында» картинаһы буйынса инша:\n\nПлан:\n1) Сыуаҡ көн һәм йылға.\n2) Әбей менән малай.\n3) Быуындар бәйләнеше.\n4) Тыныс киләсәк.\n\nИнша:\nКартинала сыуаҡ көндә йылға буйы һүрәтләнгән. Картинаның ҙур өлөшөн\nһыу биләй. Һыу тыныс аға, ул тормош ағышын хәтерләтә. Ярҙа әбей менән\nмалай ултыра. Әбей күп шатлыҡ һәм ҡайғы күргән, уның олатаһы һуғышта\nүлгән булыуы ихтимал. Ул малайға үткән тормош, ғаилә һәм Тыуған ил\nтураһында һөйләй кеүек. Малай иғтибар менән тыңлай. Был образдар\nбыуындар бәйләнешен күрһәтәләр. Картинала тыныслыҡҡа һәм матур\nкиләсәккә өмөт тойола.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":27,"key":"5-27","label":"Бүлек 5 · №27","question":"Ориентир по заголовку блока ответов: «Етегән йондоҙ»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Етегән йондоҙ»:\nБик борон заманда ер бәләкәй генә булған... Ер киңәйгәс, күк тә ҙурайған.\nТотонғандар ҙур ҡаҙан яһарға.\nАлып сүместе һауаға сорғотоп, тотоп алайым тиһә, сүмес юҡ:\nул йондоҙҙар араһына инеп боҫҡан.\nТеркәүестәр: ә, да/дә, ла/лә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":28,"key":"5-28","label":"Бүлек 5 · №28","question":"Ориентир по заголовку блока ответов: Проект «Минең ғаиләм»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Проект «Минең ғаиләм»:\n1) Ғаилә ағзалары.\n2) Ғаилә шәжәрәһе.\n3) Ата-әсәнең һөнәре.\n4) Ғаилә байрамдары.\n5) Өйҙәге бурыстар.\n6) Ғаилә традициялары.\n7) Ни өсөн мин ғаиләм менән ғорурланам?","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":29,"key":"5-29","label":"Бүлек 5 · №29","question":"Ориентир по заголовку блока ответов: «Атай менән өләсәй».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Атай менән өләсәй».\n1) Мәҡәлдәр:\n«Олоно оло ит, кесене кесе ит».\n«Ата-әсәңә ни ҡылһаң, алдыңа шул килер».\n«Әсә кеше баҫҡан һәр урын — ожмах».\n2) Өлгө: «Әсәй», «әсәйем», «ҡәҙерле әсәйем» тип өндәшәм.\nТеркәүестәр: менән, ә, кеүек.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":30,"key":"5-30","label":"Бүлек 5 · №30","question":"Ориентир по заголовку блока ответов: Һүҙлек диктанты — бирелгән һүҙҙәрҙе яҙылышы менән ятларға.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һүҙлек диктанты — бирелгән һүҙҙәрҙе яҙылышы менән ятларға.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":31,"key":"5-31","label":"Бүлек 5 · №31","question":"Ориентир по заголовку блока ответов: «Ҡәнәфер сәскәһе» — дауам:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Ҡәнәфер сәскәһе» — дауам:\nФәриҙә сәскә магазинына ашыҡты, ләкин магазин ябылып өлгөргән ине.\nУл башта ҡайғырҙы, һуңынан әсәй өсөн иң ҡиммәте һатып алынған әйбер\nтүгеллеген аңланы. Фәриҙә өйҙәге гөлдән бер сәскә алып матур итеп биҙәне,\nбүлмәне йыйыштырҙы һәм әсәһенә үҙ ҡулдары менән открытка яһаны.\nӘсәһе эштән ҡайтҡас, ҡыҙының иғтибарын күреп бик шатланды.\nТөп фекер: бүләктең хаҡы түгел, ә ихлас күңел һәм хәстәрлек мөһим.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":32,"key":"5-32","label":"Бүлек 5 · №32","question":"Ориентир по заголовку блока ответов: Ребус:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Ребус:\nРебус рәсемдәрҙән төҙөлгән. PDF-та уның яуабы текст менән бирелмәгән.\nШуға сайт өсөн был күнегеүҙе «рәсемле ребус — уҡыусы үҙе сисә» тип һаҡлау\nдөрөҫөрәк; яуапты уйлап сығарып яҙмайбыҙ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":33,"key":"5-33","label":"Бүлек 5 · №33","question":"Ориентир по заголовку блока ответов: «Ниндәй бүләк бирәләр?»","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Ниндәй бүләк бирәләр?»\nI. Проблема: төрлө илдәрҙә бүләк биреү йолалары төрлө, һәм бүләкте\nкешенең мәҙәниәтен һәм ғөрөф-ғәҙәтен иҫәпкә алып һайларға кәрәк.\nМиҫалдар:\n— Японияла хризантема император ғаиләһенә бәйле.\n— Францияла хушбуйҙы иң яҡын кеше бүләк итә.\n— Ҡытайҙа сәғәт бүләк итеү насар мәғәнә бирә.\n— Латин Америкаһында осло әйбер мөнәсәбәтте «киҫеү»ҙе аңлатырға мөмкин.\n— Боронғо Римда емеш-еләк һәм бал бүләк иткәндәр.\n\nII.\n1) Атайға/әсәйгә — кәрәкле әйбер, китап, ҡулдан яһалған бүләк, сәскә;\nолатай-өләсәйгә — йылы иҫтәлек, фотоальбом, ҡулдан яһалған бүләк;\nтуғандарға — ҡыҙыҡһыныуына тап килгән бүләк.\n2) Дуҫым менән тулыһынса килешмәйем. Сәскә оҙаҡ һаҡланмаһа ла,\nул иғтибар, хөрмәт һәм матур хис бирә. Теләһәң, сәскәгә иҫтәлекле\nоткрытка йәки икенсе бәләкәй бүләк өҫтәргә була.\n3) Ҡиммәт бүләк һәр ваҡыт иң яҡшыһы түгел. Иң мөһиме — бүләктең кешегә\nтура килеүе һәм ихлас күңелдән бирелеүе.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":34,"key":"5-34","label":"Бүлек 5 · №34","question":"Ориентир по заголовку блока ответов: «Яҙ килә».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Яҙ килә».\nЯҙ билдәләре: ер сәскәләр менән ҡаплана, ҡояш көлә, ҡоштар тыуған яҡҡа ҡайта,\nтәбиғәт йәнләнә.\nШиғырҙы шат, күтәренке һәм дәртле тон менән уҡырға кәрәк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]}]},{"title":"Бүлек 6. СӘНҒӘТ ОҪТАЛАРЫ","tasks":[{"number":1,"key":"6-1","label":"Бүлек 6 · №1","question":"Ориентир по заголовку блока ответов: «Что такое Родина?» — башҡортса:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Что такое Родина?» — башҡортса:\nТыуған ил. Һеҙ уны нисек күҙ алдына килтерәһегеҙ?\nБыл — һеҙ тыуған, донъяны тәү тапҡыр күргән һәм танып белә башлаған урын.\nБашта ул һеҙҙең өйөгөҙ, һуңынан урам, ялан, урман булды.\nҺеҙ үҫтегеҙ, шуға күрә Тыуған ил тураһында белемегеҙ ҙә артты.\nТыуған илде күберәк белер өсөн республикабыҙҙы яҡшы өйрәнергә кәрәк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":2,"key":"6-2","label":"Бүлек 6 · №2","question":"Ориентир по заголовку блока ответов: Өҙөк буйынса картина:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Өҙөк буйынса картина:\nӨлгө: Күҙ алдыма ап-аҡ ҡар менән ҡапланған ҡышҡы тәбиғәт,\nағастар, тыныс ауыл һәм һалҡын саф һауа килә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":3,"key":"6-3","label":"Бүлек 6 · №3","question":"Ориентир по заголовку блока ответов: Йәйәләрҙе асыу:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Йәйәләрҙе асыу:\n1) Кәүҙәһе күлдә, ҡойроғо ҡорола.\n2) Эҫелә лә, һыуыҡта ла ҡурҡытмай мине.\n3) Мунсала бар, өйҙә юҡ, урманда бар, ҡырҙа юҡ.\n4) Кешеләрҙе алып оса, үҙе ҡошҡа оҡшамаған.\nЙомаҡтарҙың яуабы һәр осраҡта һүҙ уйынына һәм хәрефтәргә бәйле;\nPDF тексы яуаптарҙы айырым бирмәй. Сайтта был күнегеүҙе ребус/йомаҡ\nбулараҡ ҡалдырыу дөрөҫ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":4,"key":"6-4","label":"Бүлек 6 · №4","question":"Ориентир по заголовку блока ответов: 1) Теркәүестәр: тик, әммә (текста осраған урындары буйынса).","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"1) Теркәүестәр: тик, әммә (текста осраған урындары буйынса).\n2) Тәржемә:\nсигенде — отступил;\nюлсы — путник;\nҡарашы — взгляд;\nмоңһоу — грустный;\nғорур — гордый;\nһиҙеп була — можно почувствовать;\nтынғыһыҙ — беспокойный.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":5,"key":"6-5","label":"Бүлек 6 · №5","question":"Ориентир по заголовку блока ответов: Һорауҙарға өлгө яуаптар:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һорауҙарға өлгө яуаптар:\n1) Буш ваҡытта китап уҡыйым, музыка тыңлайым, спорт менән шөғөлләнәм.\n2) Эйе, музыка тыңларға яратам. Күберәк заманса һәм халыҡ музыкаһын тыңлайым.\n3) Башҡорт композиторҙарынан Хөсәйен Әхмәтов, Заһир Исмәғилев һәм башҡалар билдәле.\n4) Өлгө: концертта, театрҙа йәки мәктәп байрамында тере музыка тыңлағаным бар.\n5) Башҡорт халҡының милли музыка ҡоралдарының береһе — ҡурай.\n6) Өлгө: спорт/музыка/тел түңәрәгенә йөрөйөм.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":6,"key":"6-6","label":"Бүлек 6 · №6","question":"Ориентир по заголовку блока ответов: Ҡумыҙ тураһында:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Ҡумыҙ тураһында:\nҠумыҙҙа уйнау теш һәм ауыҙ аппараты өсөн гимнастика була,\nтын юлдарына һәм кешенең физик-психологик торошона тәьҫир итә.\nБармаҡтарҙың хәрәкәте нервыларҙы әүҙемләштерә.\nТөп фекер: ҡумыҙ — боронғо һәм бик киң таралған музыка ҡоралы.\n\n«Һай, ҡумыҙы, ҡумыҙы!» буйынса:\n1) Ҡумыҙ Европа, Алыҫ Көнсығыш, Көньяҡ Америка, Африка, Волга буйы һәм\nбашҡа бик күп халыҡтарҙа таралған.\n2) Был ҡоралдың төҙөлөшө ябай, боронғо һәм төрлө халыҡтарҙа үҙаллы\nбарлыҡҡа килә алған; кешеләр араһындағы мәҙәни бәйләнештәр ҙә таралыуға ярҙам иткән.\n3) Шәхси яуап. Өлгө: Эйе, ҡумыҙҙы күргәнем һәм уның тауышын ишеткәнем бар.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":7,"key":"6-7","label":"Бүлек 6 · №7","question":"Ориентир по заголовку блока ответов: Роберт Заһретдинов:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Роберт Заһретдинов:\nУл — билдәле ҡумыҙсы, виртуоз башҡарыусы.\n1) Иң ҙур еңеүҙәренең береһе: 1991 йылда Якутск-Сахала ЮНЕСКО үткәргән\nII халыҡ-ара ҡумыҙ конгресында 22 илдән килгән 200-ләп башҡарыусы араһында\n«Донъя виртуоз ҡумыҙсыһы» исемен яулауы.\n2) Теркәүестәрҙе текст буйынса билдәләргә: һәм, менән, ә, лә/лә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":8,"key":"6-8","label":"Бүлек 6 · №8","question":"Ориентир по заголовку блока ответов: Яңы һүҙҙәрҙе һүҙлек менән эшләү — шәхси.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Яңы һүҙҙәрҙе һүҙлек менән эшләү — шәхси.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":9,"key":"6-9","label":"Бүлек 6 · №9","question":"Ориентир по заголовку блока ответов: Һүҙбәйләнештәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һүҙбәйләнештәр:\nвыступление участников — ҡатнашыусыларҙың сығышы;\nучастники кружка — түңәрәк ҡатнашыусылары;\nхудожественная самодеятельность — художестволы үҙешмәкәрлек;\nвыступление на концерте — концертта сығыш яһау;\nпраздничный концерт — байрам концерты;\nпроизвести на зрителей сильное впечатление — тамашасыларҙа көслө тәьҫир ҡалдырыу;\nмастерски исполнить башкирские и татарские народные танцы —\nбашҡорт һәм татар халыҡ бейеүҙәрен оҫта башҡарыу;\nпесни русских, башкирских композиторов —\nрус һәм башҡорт композиторҙарының йырҙары;\nбашкирские и русские народные песни — башҡорт һәм рус халыҡ йырҙары;\nкаждый номер — һәр номер;\nномер концерта — концерт номеры;\nдолго аплодировать — оҙаҡ ҡул сабыу;\nсамодеятельные артисты — үҙешмәкәр артистар.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":10,"key":"6-10","label":"Бүлек 6 · №10","question":"Ориентир по заголовку блока ответов: Һорауҙарға өлгө:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һорауҙарға өлгө:\n1) Класташтарым араһында йырлаусылар, бейеүселәр һәм музыка ҡоралында уйнаусылар бар.\n2) Ҡалала/ауылда балалар сәнғәт мәктәбе бар тип яуап бирергә мөмкин\n(үҙ урынығыҙға яраҡлаштырығыҙ).\n3) Эйе, мәктәптә атай-әсәйҙәр өсөн байрам концерттары ҡуябыҙ.\n4) Өлгө: мәктәпкә артистар һәм музыканттар осрашыуға килгәне бар.\n5) Өлгө: ҡайһы бер класташтарым киләсәктә музыка йәки сәнғәт менән бәйле һөнәр һайларға теләй.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":11,"key":"6-11","label":"Бүлек 6 · №11","question":"Ориентир по заголовку блока ответов: Диалог өлгөһө:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Диалог өлгөһө:\n— Һин кисә концертта булдыңмы?\n— Эйе, булдым.\n— Ҡайһы номер нығыраҡ оҡшаны?\n— Башҡорт халыҡ бейеүе оҡшаны.\n— Ни өсөн?\n— Артистар бик оҫта һәм дәртле бейене.\n— Тамашасылар нисек ҡаршы алды?\n— Оҙаҡ ҡул саптылар.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":12,"key":"6-12","label":"Бүлек 6 · №12","question":"Ориентир по заголовку блока ответов: Теркәүестәр менән киңәйтеү:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Теркәүестәр менән киңәйтеү:\n1) Урамда һалҡын ҡыш, ләкин беҙ саф һауала йөрөйбөҙ.\n2) Байрам килеп етте һәм бөтәһе лә шатланды.\n3) Минең өсөн әсәнән бөйөгөрәк кеше юҡ.\n4) Донъяла һөнәрҙәр күп, шуға күрә һәр кем үҙенә оҡшағанын һайлай ала.\n5) Ҡоштар ҡайтыуға күп ҡалманы, сөнки яҙ яҡынлаша.\n6) Аквариумдағы балыҡтарҙы ҡустым тәрбиәләй, ә мин уға ярҙам итәм.\n7) Китап — һинең дуҫың һәм кәңәшсең.\n8) Әсәй эштән ҡайтыуға һеңлем менән өйҙө йыйыштырып бөттөк.\n9) Беҙҙең ғаилә газета-журналдарға яҙылды, сөнки беҙ уҡырға яратабыҙ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":13,"key":"6-13","label":"Бүлек 6 · №13","question":"Ориентир по заголовку блока ответов: Рәшиҙә Туйсина:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Рәшиҙә Туйсина:\n1) Ул — билдәле башҡорт бейеүсеһе, башҡорт сәхнә сәнғәтенең күренекле оҫтаһы.\n2) Өлгө: шулай уҡ Фәйзи Ғәскәров ансамбле бейеүселәре һәм хәҙерге халыҡ\nбейеүе оҫталары тураһында өҫтәмә сығанаҡтан мәғлүмәт алырға мөмкин.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":14,"key":"6-14","label":"Бүлек 6 · №14","question":"Ориентир по заголовку блока ответов: Бейеү тураһында:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Бейеү тураһында:\nБейеү — бик боронғо сәнғәт. Кешеләр һүҙ барлыҡҡа килгәнгә тиклем үк\nхәрәкәттәр менән хистәрен һәм ваҡиғаларҙы күрһәтергә тырышҡан.\nАу, хеҙмәт һәм хайуандарҙың хәрәкәттәре бейеүҙә сағылған.\nБашҡорт ир-егеттәр бейеүҙәрендә атта сабыу, көс һәм ҡыйыулыҡ һыҙаттары,\nҡатын-ҡыҙ бейеүҙәрендә нәфислек һәм көнкүреш хәрәкәттәре күренә.\n«Ете ҡыҙ» тураһында өҫтәмә мәғлүмәт — проект/өҫтәмә сығанаҡ талап иткән эш.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":15,"key":"6-15","label":"Бүлек 6 · №15","question":"Ориентир по заголовку блока ответов: Диалог темалары:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Диалог темалары:\n«Театрҙа»:\n— Спектакль оҡшанымы?\n— Эйе, артистар бик оҫта уйнаны.\n— Ҡайһы герой иҫтә ҡалды?\n— Төп герой.\n\n«Касса янында»:\n— Ике билет бирегеҙ әле.\n— Ҡайһы спектаклгә?\n— Киске спектаклгә.\n— Рәхим итегеҙ.\n\nҠурай һәм ҡумыҙ:\nОҡшашлығы — икеһе лә башҡорт халыҡ музыка ҡоралдары, халыҡ көйҙәрен башҡарыуҙа ҡулланыла.\nАйырмаһы — ҡурай өрөп уйнай торған тынлы ҡорал, ә ҡумыҙ ауыҙ янына ҡуйып\nсиртеп уйнай торған бәләкәй ҡорал.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]}]},{"title":"Бүлек 7. ИСЕМЕҢ МАТУР, КЕМДӘР ҠУШҠАН?","tasks":[{"number":1,"key":"7-1","label":"Бүлек 7 · №1","question":"Ориентир по заголовку блока ответов: Тексты тултырыу:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Тексты тултырыу:\nБашҡорт исемдәренең тәрбиәүи мәғәнәһе лә бар.\nБала бәләкәйҙән исеменең мәғәнәһен белеп, исемен яратып үҫһә,\nунда үҙенең милләтенә ҡарата ғорурлыҡ уяна.\nҺәр кеше исемен ғорур йөрөтһөн, боҙмаһын, үҙгәртмәһен, оялмаһын,\nсөнки атай-әсәй был исемде яратып ҡушҡан.\n\n1) Гөлназ, Гөлдәр кеүек исемдәрҙе матур итеп, дөрөҫ әйтергә кәрәк;\nисемде мыҫҡыллап боҙоу дөрөҫ түгел.\n2) «Исем туйы» — балаға исем ҡушыу менән бәйле ғаилә байрамы/йолаһы.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":2,"key":"7-2","label":"Бүлек 7 · №2","question":"Ориентир по заголовку блока ответов: Исем ҡушҡандағы теләктәрҙең мәғәнәһе:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Исем ҡушҡандағы теләктәрҙең мәғәнәһе:\n1) Ата-әсәңә терәк булып үҫ.\n2) Татлы телле, матур һүҙле бул.\n3) Изгелекле һәм файҙалы кеше бул.\n4) Ватаныңа дан килтер.\n5) Исемеңә лайыҡ кеше булып үҫ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":3,"key":"7-3","label":"Бүлек 7 · №3","question":"Ориентир по заголовку блока ответов: «Гөл» менән башланған исемдәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Гөл» менән башланған исемдәр:\nГөлназ, Гөлдәр, Гөлсәсәк, Гөлшат, Гөлфиә, Гөлнур, Гөлсөм, Гөлназира.\n\nДиалог:\n— Һинең исемең нимә?\n— Минең исемем Гөлназ.\n— Исемең нимә аңлата?\n— «Гөл» — сәскә, ә исем матурлыҡ менән бәйле.\n— Исемең оҡшаймы?\n— Эйе, бик оҡшай.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":4,"key":"7-4","label":"Бүлек 7 · №4","question":"Ориентир по заголовку блока ответов: Бәйләүестәр менән һөйләмдәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Бәйләүестәр менән һөйләмдәр:\nТыныслыҡ өсөн бөтәбеҙ ҙә яуаплы.\nМин көн һайын уҡыйым.\nКүпер йылға аша үтә.\nБеҙ батырҙар хаҡында уҡыйбыҙ.\nМин Илдар менән мәктәпкә барҙым.\nМин өйгә тиклем йәйәү ҡайттым.\nҠыш буйына ҡар ятты.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":5,"key":"7-5","label":"Бүлек 7 · №5","question":"Ориентир по заголовку блока ответов: 1) Урманға тиклем беҙҙе Мансур оҙатты.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"1) Урманға тиклем беҙҙе Мансур оҙатты.\n2) Йортонан иртә сығыуына ҡарамаҫтан, Юлиә киноға һуңланы.\n3) Олатайым мине мәктәпкә саҡлы/тиклем оҙатты.\n4) Айрат Азаматҡа ҡарағанда ҙурыраҡ.\n5) Көн һыуыҡ булыуға ҡарамаҫтан, беҙ урамға сыҡтыҡ.\n6) Атайым юл буйы йырлап барҙы.\n7) Беҙҙең мәктәпкә ҡаршы аҙыҡ-түлек магазины бар.\n8) Шүлгәнташ мәмерйәһе хаҡында сәғәт буйы һөйләне.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":6,"key":"7-6","label":"Бүлек 7 · №6","question":"Ориентир по заголовку блока ответов: 1) Беҙ былтыр көн һайын дәрестән һуң урманға бара инек.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"1) Беҙ былтыр көн һайын дәрестән һуң урманға бара инек.\n2) Шуның арҡаһында беҙ орлоҡ йыйыу эшен ваҡытында башҡарҙыҡ.\n3) Ошо файҙалы эшебеҙ өсөн беҙгә рәхмәт әйттеләр.\nҠалған һөйләмдәрҙә лә контекстҡа ҡарап «тиклем/ҡәҙәр/һуң/өсөн/арҡаһында» ҡулланыла.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":7,"key":"7-7","label":"Бүлек 7 · №7","question":"Ориентир по заголовку блока ответов: Исем кешенең яҙмышына тәьҫир итәме?","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Исем кешенең яҙмышына тәьҫир итәме?\nӨлгө: Исем үҙе яҙмышты тулыһынса билдәләмәй, ләкин кеше үҙ исеменә\nлайыҡ булырға тырышырға мөмкин. Кешенең абруйын уның эштәре һәм холҡо булдыра.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":8,"key":"7-8","label":"Бүлек 7 · №8","question":"Ориентир по заголовку блока ответов: Исемдәрҙең мәғәнәһе — учебникта бирелгән аңлатмаларҙы хәтерҙә ҡалдырыу.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Исемдәрҙең мәғәнәһе — учебникта бирелгән аңлатмаларҙы хәтерҙә ҡалдырыу.\nӨлгө: Айһылыу — ай кеүек һылыу; Гөлназ — сәскә кеүек наҙлы;\nИлдар — ил менән бәйле ир-егет исеме; Батыр — ҡыйыу кеше мәғәнәһе.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":9,"key":"7-9","label":"Бүлек 7 · №9","question":"Ориентир по заголовку блока ответов: Шәхси эш өсөн өлгө:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Шәхси эш өсөн өлгө:\n«Минең исемем ________. Был исемде миңә атай-әсәйем ҡушҡан.\nУның мәғәнәһе — ________. Мин исемемде яратам».\n\n«Исемең матур, кем ҡушҡан?» байрамы:\n1) Исемдәр тарихы.\n2) Исемдәрҙең мәғәнәһе.\n3) Ғаилә исем ҡушыу тарихы.\n4) Викторина.\n5) Йомғаҡ.\n\nҒаилә шәжәрәһе:\nолатай-өләсәй → атай-әсәй → балалар.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":10,"key":"7-10","label":"Бүлек 7 · №10","question":"Ориентир по заголовку блока ответов: 1 апрель һорауына яуап:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"1 апрель һорауына яуап:\nШаярыу кешене рәнйетергә, ҡурҡытырға йәки зыян килтерергә тейеш түгел.\nӨлгө: «Бөгөн контроль булмай икән!» — тип әйтеп, шунда уҡ\n«1 апрель менән!» — тип көлөп ҡуйырға мөмкин.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":11,"key":"7-11","label":"Бүлек 7 · №11","question":"Ориентир по заголовку блока ответов: Проект «Исемдәрҙә ил тарихы»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Проект «Исемдәрҙә ил тарихы»:\n1) Боронғо башҡорт исемдәре.\n2) Ислам менән килгән исемдәр.\n3) Тәбиғәт, батырлыҡ һәм матурлыҡ менән бәйле исемдәр.\n4) Совет осорондағы исемдәр.\n5) Хәҙерге исемдәр.\n6) Ғаиләбеҙҙәге исемдәр тарихы.\n7) Йомғаҡ: исемдәр халыҡ тарихын һәм мәҙәниәтен һаҡлай.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]}]},{"title":"Бүлек 8. БОРОН-БОРОН ЗАМАНДА...","tasks":[{"number":1,"key":"8-1","label":"Бүлек 8 · №1","question":"Ориентир по заголовку блока ответов: Нимә ул әкиәт?","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Нимә ул әкиәт?\nӘкиәт — халыҡтың уй-хыялын, донъяға ҡарашын һәм тормош тәжрибәһен сағылдырған,\nуйҙырма ваҡиғаларға ҡоролған ауыҙ-тел ижады әҫәре. Әкиәттә тылсымлы хәлдәр,\nбатырҙар, хайуандар һәм ғәҙәти кешеләр тураһында һөйләнергә мөмкин.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":2,"key":"8-2","label":"Бүлек 8 · №2","question":"Ориентир по заголовку блока ответов: «Ҡан-ҡәрҙәш».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Ҡан-ҡәрҙәш».\nНи өсөн шулай атала?\nХан егеттең әсәһе һөтө ҡушылған икмәкте ашай, шуға күрә үҙен егет менән\n«ҡан-ҡәрҙәш» кеүек бәйләнгән тип иҫәпләй һәм уны үлтермәй.\n\n1) Хан ҡаты бәғерле, ҡанһыҙ һәм уҫал булған.\n2) Егеттең ата-әсәһе ярлы йәшәгән.\n3) Әсәһе егеткә үҙ һөтө ҡушылған икмәк биреп ебәргән.\n4) Хан икмәкте ашағас, егет менән туғанлыҡ бәйләнеше бар тип ҡабул иткән,\nшуға уны үлтермәгән.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":3,"key":"8-3","label":"Бүлек 8 · №3","question":"Ориентир по заголовку блока ответов: Сәскә исемдәре:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Сәскә исемдәре:\nодуванчик — бәпембә;\nзверобой — һары мәтрүшкә;\nколокольчик — ҡыңғырау сәскә;\nподснежник — умырзая;\nмать-и-мачеха — үгәй инә үләне;\nнезабудка — күгәрсен күҙ;\nгвоздика — ҡәнәфер сәскә;\nдушица — мәтрүшкә;\nтысячелистник — меңьяпраҡ;\nшиповник — гөлйемеш;\nподорожник — юл япрағы;\nподсолнух — көнбағыш.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":4,"key":"8-4","label":"Бүлек 8 · №4","question":"Ориентир по заголовку блока ответов: I. «Зәңгәр тауҙар илендә».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I. «Зәңгәр тауҙар илендә».\nШиғырҙа тылсымлы алтын мөгөҙлө, етеҙ болан һүрәтләнә.\nУл бейек тауҙарҙы, ҡаяларҙы ярата. Шиғыр әкиәт атмосфераһы тыуҙыра,\nтәбиғәттең матурлығын һәм ирек һөйгән йәнлекте күрһәтеп тора.\n\nII. «Кем аҡыллыраҡ?»\nДөрөҫ ҡылымдар:\nБорон заманда бер бабай менән айыу дуҫлашҡан.\nУлар бергәләп шалҡан сәскәндәр.\nБына уңышты йыйыу ваҡыты еткән.\n\nДауам:\nШалҡан өлгөргәс, бабай айыуға:\n— Һин өҫкө өлөшөн ал, мин тамырын алам, — тигән.\nАйыу ризалашҡан, ләкин уға япраҡ ҡына эләккән.\nИкенсе йыл улар бойҙай сәскән. Айыу был юлы тамырын алам, тигән.\nБабай башаҡтарҙы алған, ә айыуға файҙаһыҙ тамыр ҡалған.\nШулай итеп, бабай айыуҙан аҡыллыраҡ булып сыҡҡан.\n\n1) Әкиәт ике геройҙың аҡылын сағыштырған өсөн «Кем аҡыллыраҡ?» тип атала.\n2) Айыу көслө, ҙур, ышаныусан һәм бер аҙ ябай күңелле итеп күҙ алдына килә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":5,"key":"8-5","label":"Бүлек 8 · №5","question":"Ориентир по заголовку блока ответов: Юрий Гагариндың әсәһе тураһындағы текстың башҡортса мәғәнәһе:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Юрий Гагариндың әсәһе тураһындағы текстың башҡортса мәғәнәһе:\nБеренсе космонавтың әсәһе Анна Тимофеевна Гагарина янына пионерҙар йыш килгән.\nБер ваҡыт улар: «Кеше характерында ниндәй сифаттарҙы иң юғары баһалайһығыҙ?» —\nтип һораған. Ул изгелек, ҡыйыулыҡ һәм батырлыҡты атаған.\nЮра бәләкәйҙән үк бик ҡыйыу һәм изге күңелле булған.\nМәктәптә ул артта ҡалған иптәштәренә ярҙам иткән, кесе һәм көсһөҙҙәрҙе яҡлаған.\n\nМин үҙ иткән сифаттар: изгелек, ҡыйыулыҡ, намыҫлылыҡ, ярҙамсыллыҡ,\nтүҙемлелек һәм яуаплылыҡ.\n\nФакиһа Туғыҙбаева тураһында:\nФакиһа Һаҙый ҡыҙы Туғыҙбаева — Башҡортостандың халыҡ шағирәһе.\nУл Бүздәк районы Ҡаңны ауылында тыуған, Башҡорт дәүләт университетын тамамлаған.\nУның «Мең ялҡыны», «Күҙ ҡараһы», «Йондоҙ асам», «Сәғәт моңо»,\n«Фатихамды бирәм һиңә», «Минең ҡошом Һомай» китаптары бар.\nБалалар өсөн дә күп шиғырҙар, хикәйәләр һәм әкиәттәр яҙған.\n\n«Тайыштабан ниңә уйнарға сыҡманы?»\n1) Тайыштабан Оҙонғолаҡты һалҡын көҙ көнөндә, айыу балаһы һуңғы тапҡыр уйнарға\nсыҡҡанда осрата.\n2) Оҙонғолаҡ уға сана күрһәтә.\n3) Тайыштабан сана күрмәгән, сөнки айыуҙар ҡышын йоҡлай һәм ул ҡарлы ҡышҡы\nуйындарҙы белмәй.\n4) Оҙонғолаҡ тәҙрә төбөнә килеп һыҙғырып саҡыра.\n5) Уларҙың мөнәсәбәте дуҫтарса: Оҙонғолаҡ Тайыштабанды үпкәләтергә теләмәй,\nуны тауға саҡырырға вәғәҙә итә.\n6) Тайыштабан уйнарға сыҡмай, сөнки ҡыш еткәс айыуҙар өңдәрендә ҡышҡы йоҡоға тала.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":6,"key":"8-6","label":"Бүлек 8 · №6","question":"Ориентир по заголовку блока ответов: 1) Ғинуарҙа көндәр бик ҡыҫҡа булды. Февралдә көндәр оҙоная башлай.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"1) Ғинуарҙа көндәр бик ҡыҫҡа булды. Февралдә көндәр оҙоная башлай.\n2) Ғинуарҙа ҡояш йылытмай. Февраль аҙағында ҡояш ерҙе йылыта башлай.\n3) Ғинуарҙа ҡар ап-аҡ була. Февралдә ҡар ирей/ҡарая башлай.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":7,"key":"8-7","label":"Бүлек 8 · №7","question":"Ориентир по заголовку блока ответов: Йомаҡтар:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Йомаҡтар:\n1) айыу;\n2) ҡуян;\n3) тейен;\n4) төлкө;\n5) терпе.\n\nХайуан тураһында өлгө:\nТейен урманда йәшәй. Ул ағас баштарында бик етеҙ йөрөй.\nСәтләүек, орлоҡ һәм бәшмәк менән туҡлана. Ҡышҡа аҙыҡ туплай.\n\nҮҙегеҙҙе тикшерегеҙ:\n1) Әкиәттәр халыҡтың тормош тәжрибәһен, аҡылын һәм әхлаҡи ҡиммәттәрен һаҡлай,\nяҡшылыҡ менән яманлыҡты айырырға өйрәтә.\n2) Өлгө: «Урал батыр», «Кем аҡыллыраҡ?», «Ҡан-ҡәрҙәш» һәм башҡа әкиәттәр.\n3) Өлгө: А. С. Пушкин, Ш. Перро, Г. Х. Андерсен әкиәттәрен уҡығаным бар.\n\nЯл минуттары — хәрефтәрҙе дөрөҫ урынлаштырыу:\nЛЫҠҘЫ → ҠЫҘЫЛ\nҠА → АҠ\nККҮ → КҮК\nОҺРО → ҺОРО\nШӘЛЙЕ → ЙӘШЕЛ\nААҠР → ҠАРА\nЫҺАР → ҺАРЫ\nЛА → АЛ","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]}]},{"title":"Бүлек 9. БЕРҘӘМЛЕК, ДУҪЛЫҠ, ТЫНЫСЛЫҠ","tasks":[{"number":1,"key":"9-1","label":"Бүлек 9 · №1","question":"Ориентир по заголовку блока ответов: Дуҫлыҡ ҡағиҙәләре:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Дуҫлыҡ ҡағиҙәләре:\n— дуҫҡа ышанырға;\n— кәрәк саҡта ярҙам итергә;\n— шатлыҡты ла, ауырлыҡты ла бүлешергә;\n— дуҫтың яҡшы сифаттарын күрергә;\n— етешһеҙлеген төҙәтергә ярҙам итергә;\n— тоғро һәм ғәҙел булырға.\n\n2) Өлгө: Эйе, минең дуҫым менән мөнәсәбәтебеҙ ошо ҡағиҙәләргә тап килә:\nбер-беребеҙгә ярҙам итәбеҙ һәм сер һаҡлайбыҙ.\n3) Һорауҙар:\n— Ысын дуҫ ниндәй була?\n— Дуҫҡа ҡасан ярҙам итергә кәрәк?\n— Ни өсөн дуҫтар бер-береһенә ышанырға тейеш?\n4) Һөйләмдәр:\nМинең ышаныслы дуҫым бар.\nДуҫлыҡ кешене көслө итә.\nЫсын дуҫ ауыр ваҡытта һынала.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":2,"key":"9-2","label":"Бүлек 9 · №2","question":"Ориентир по заголовку блока ответов: Миңлеғәле Ғөбәйҙуллин:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Миңлеғәле Ғөбәйҙуллин:\n1) Ул дошман дзотының амбразураһын үҙ кәүҙәһе менән ҡаплап, иптәштәренә алға\nбарырға мөмкинлек биргән.\n2) Унан алда шундай батырлыҡты Александр Матросов эшләгән.\n3) Учебниктағы бирем Шакирйән Мөхәмәтйәнов (Александр Матросов) исемен бәйләй;\nул да дошман ут нөктәһен кәүҙәһе менән ҡаплап батырлыҡ күрһәткән.\n4) Һүҙбәйләнештәрҙе уҡыу — устно.\n5) Һуңғы һөйләмдәрҙең мәғәнәһе: батырҙарҙың ҡаһарманлығы Тыуған ил һәм\nкиләсәк быуындар хәтерендә мәңге ҡала.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":3,"key":"9-3","label":"Бүлек 9 · №3","question":"Ориентир по заголовку блока ответов: Муса Гәрәев:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Муса Гәрәев:\n1) Муса Гәрәев — Бөйөк Ватан һуғышы осоусыһы, ике тапҡыр Советтар Союзы Геройы.\n2) Мәктәптә ул тырышлығы, ныҡышмалылығы һәм һүҙендә тороуы менән айырылған.\n3) Эйе, был сифаттар һуғышта уға ауыр хәлдәрҙә ныҡ булырға ярҙам иткән.\n4) Тыныслыҡ өсөн кешеләр бер-береһен хөрмәт итергә, бәхәстәрҙе көс ҡулланмай\nхәл итергә, төрлө халыҡтар менән татыу йәшәргә тейеш.\n5) Текстағы бәйләүес/теркәүестәрҙән: һәм, менән, өсөн, ә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":4,"key":"9-4","label":"Бүлек 9 · №4","question":"Ориентир по заголовку блока ответов: Мәҡәлдәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Мәҡәлдәр:\nМәғәнәһе — батырлыҡ, илде яҡлау, ҡыйынлыҡтан ҡурҡмау.\nӨлгө: «Батыр яуҙа беленер» — кешенең ҡыйыулығы ауыр һынауҙа күренә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":5,"key":"9-5","label":"Бүлек 9 · №5","question":"Ориентир по заголовку блока ответов: Шиғыр буйынса:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Шиғыр буйынса:\n1) Автор күп дуҫтары, киң һәм матур Тыуған иле менән ғорурлана.\n2) Географик атамалар: Аҡъяр, Себер, Ташкент, Бөрйән, Инйәр, Арғаяш.\n3) Кеше исемдәре: Гүзәл, Айсыуаҡ, Көнсыуаҡ, Сәлимә, Әминә, Хәҙисә.\n4) Башҡорт аштары/эсемлектәре: ваҡ бәлеш, ҡаҙ ите, бишбармаҡ, ҡаҙылыҡ, балан,\nҡымыҙ.\n5) «Алъяпҡыс» — ҡушма һүҙ; «Аҡъяр» — географик яңғыҙлыҡ исеме, баш хәрефтән яҙыла.\n6) Өлгө: Минең дуҫтарым Өфөлә, районда һәм башҡа ҡалаларҙа йәшәй.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":6,"key":"9-6","label":"Бүлек 9 · №6","question":"Ориентир по заголовку блока ответов: Һүрәт буйынса өлгө:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һүрәт буйынса өлгө:\nБер уҡыусы ауыр сумка күтәргән иптәшенә ярҙам итә.\nДуҫтар бер-береһенең хәлен күреп, ярҙам ҡулы һуҙырға тейеш.\nЫсын дуҫлыҡ бәләкәй генә изге эштәрҙә лә күренә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":7,"key":"9-7","label":"Бүлек 9 · №7","question":"Ориентир по заголовку блока ответов: Умырзая:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Умырзая:\nУмырзая — яҙҙың иң тәүге сәскәләренең береһе. Ул ҡар ирей башлағас уҡ ҡалҡып сыға.\nШиғырҙа ул яҙҙың килеүен, тәбиғәттең уяныуын белдерә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":8,"key":"9-8","label":"Бүлек 9 · №8","question":"Ориентир по заголовку блока ответов: Дөрөҫ һөйләмдәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Дөрөҫ һөйләмдәр:\n1) Ҡояш көндән-көн нығыраҡ йылыта.\n2) Тәүге бәләкәй йырғанаҡтар күренә.\n3) Тәбиғәт көндән-көн йәнләнә бара.\n4) Ҡар һыуҙары тауҙарҙан шаулап аға.\n5) Тәүге сәскәләр ҡалҡып сыҡты.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":9,"key":"9-9","label":"Бүлек 9 · №9","question":"Ориентир по заголовку блока ответов: «Тауышһыҙ Талип».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Тауышһыҙ Талип».\n1) План:\n1. Талиптың «ауырыуы».\n2. Кластағы хәл.\n3. Дуҫтарҙың һәм уҡытыусының борсолоуы.\n4. Серҙең асылыуы.\n2) Диалог итеп сәхнәләштереү — ролле эш.\n3) Текста Мәжит Ғафури тураһында һүҙ бара.\n4) Талип муйынын шарф һәм мамыҡ шәл менән ураған, сөнки ул тамағы ауыртҡан һәм\nтауышы сыҡмай тип күрһәтергә теләгән.\n5) Мөнәсәбәт һүҙҙәр: әллә, ысынлап та, икән, инде кеүек һүҙҙәр контекстта\nавторҙың/геройҙың мөнәсәбәтен күрһәтә.\n6) Төп мәғәнә: башҡаларҙы алдарға тырышыу барыбер асыла; дөрөҫөн һөйләү яҡшыраҡ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":10,"key":"9-10","label":"Бүлек 9 · №10","question":"Ориентир по заголовку блока ответов: Диалогтар:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Диалогтар:\n1) Коридорҙа йүгергән уҡыусы:\n— Туҡта, коридорҙа йүгерергә ярамай бит!\n— Ғәфү ит, ашығып киттем.\n— Һаҡ бул, кемделер бәреп йығыуың мөмкин.\n— Дөрөҫ, башҡа йүгермәм.\n\n2) Дәрескә һуңлаған уҡыусы:\n— Ни өсөн һуңланың?\n— Ғәфү итегеҙ, автобус һуң килде.\n— Икенсе тапҡыр иртәрәк сыҡ.\n— Ярай, мотлаҡ.\n\n3) Физкультура дәресендә:\n— Ҡулың ауыртамы әллә?\n— Эйе, әҙерәк ауырта.\n— Улай булғас, уҡытыусыға әйт.\n— Дөрөҫ, хәҙер әйтәм.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":11,"key":"9-11","label":"Бүлек 9 · №11","question":"Ориентир по заголовку блока ответов: Мәҡәлдәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Мәҡәлдәр:\n1) Дуҫтың дуҫлығы яуҙа беленә.\n2) Ҡош — ҡанат менән, кеше дуҫлыҡ менән көслө.\n3) Яңы ҡолаҡсын бүрек таптым тип, иҫкеһен ташлама.\n4) Дуҫлы кеше юғалмаҫ.\n5) Айырылмаҫтай дуҫыңа ауыр һүҙ әйтмә.\n6) Ил өҫтөндә йөҙ дуҫың булһын.\n7) Күпте яманлаған дуҫһыҙ ҡалыр.\nМәғәнә: дуҫлыҡты һаҡларға, дуҫҡа ауыр һүҙ әйтмәҫкә һәм ауыр саҡта ярҙам итергә кәрәк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":12,"key":"9-12","label":"Бүлек 9 · №12","question":"Ориентир по заголовку блока ответов: Мөнәсәбәт һүҙҙәре менән өлгө:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Мөнәсәбәт һүҙҙәре менән өлгө:\nӘлбиттә, ысын дуҫ ярҙамға килә.\nМинеңсә, дуҫлыҡ ышанысҡа ҡорола.\nБәлки, ул бөгөн беҙгә килер.\nҠыҙғанысҡа ҡаршы, ҡайһы ваҡыт кешеләр дуҫлыҡтың ҡәҙерен һуң аңлай.\n\nФәүзиә Рәхимғолова тураһында:\nУчебник буйынса ул балалар һәм ололар өсөн күп китаптар яҙған шағирә/яҙыусы.\nӨлгө: Минең ышаныслы дуҫым бар, беҙ бер-беребеҙгә ярҙам итәбеҙ.\n\n«Дуҫтарым»:\n1) Шиғырҙа авторҙың дуҫтары — китаптар.\n2) Өлгө: Эйе, минең дә яратҡан китаптарым бар.\n3) «Мең серле» — китапта күп сер һәм белем бар;\n«ҡаршыма сығыр» — һәр уҡығанда яңы донъя аса;\n«киләсәккә илтә» — белем киләсәккә юл аса;\n«бүлмәлә ултыр» — өйҙә ултырып та китап аша алыҫ донъяларҙы белергә мөмкин.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":13,"key":"9-13","label":"Бүлек 9 · №13","question":"Ориентир по заголовку блока ответов: «Ҡайын һыуы»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Ҡайын һыуы»:\nТекст/һүрәттәрҙең төп мәғәнәһе — ҡайын һутын алғанда ағасҡа зыян килтермәҫкә кәрәк.\n1) Текстты һүрәттәрҙе һүҙҙәр менән алмаштырып һөйләү.\n2) Ҡайындың ҡороуына уның кәүҙәһен ныҡ яралау, һутты артыҡ күп алыу сәбәп булырға мөмкин.\n3) Ҡайын һутын эсергә мөмкин, ләкин ағасты яралап, уны ҡоротоу дөрөҫ түгел.\n4) Шәхси яуап: үҙегеҙҙең яҡтағы шишмә исемдәрен яҙығыҙ.\n5) Шишмәләрҙе таҙартырға, сүп ташламаҫҡа, тирә-яғын һаҡларға, һыуын бысратмаҫҡа кәрәк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":14,"key":"9-14","label":"Бүлек 9 · №14","question":"Ориентир по заголовку блока ответов: «Болон»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Болон»:\n1) Шиғырҙа болон тәбиғәте, сәскәләр һәм яҡты йәйге күренештәр һүрәтләнгән,\nшуға ул «Болон» тип атала.\n2) «Болон нурҙар сәсеп ята» — сәскәләрҙең төҫө, ҡояш нурҙары һәм\nматурлыҡ болонды ялтырап торғандай итеп күрһәтә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":15,"key":"9-15","label":"Бүлек 9 · №15","question":"Ориентир по заголовку блока ответов: Урман тураһында текст:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Урман тураһында текст:\nТөп фекер — урман ҙур тәбиғи байлыҡ: ул саф һауа, ағас, дарыу үҫемлектәре,\nйәнлектәргә йәшәү урыны бирә. Урманды һаҡлау, янғындан һәм законһыҙ ҡырҡыуҙан\nҡурсалау кәрәк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":16,"key":"9-16","label":"Бүлек 9 · №16","question":"Ориентир по заголовку блока ответов: Класташ портреты — өлгө:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Класташ портреты — өлгө:\nМинеңсә, Айҙар — тыныс һәм ярҙамсыл малай. Ул, әлбиттә, спортты ярата.\nБәлки, уның иң яҡшы сифаты — тоғролоҡ. Ул дуҫтарына бер ҡасан да ярҙамдан баш тартмай.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":17,"key":"9-17","label":"Бүлек 9 · №17","question":"Ориентир по заголовку блока ответов: I. Хайуандар:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I. Хайуандар:\nБеҙҙең яҡта осрай: айыу, төлкө, бүре, ҡуян, һеләүһен, терпе, ҡоралай.\nБашҡа тәбиғәт зоналарына хас: жираф, маймыл, морж, фил, арыҫлан, юлбарыҫ.\n\nII. Йыл миҙгелдәре:\nҠыш, яҙ, йәй, көҙ — дүрт миҙгел.\nАйҙар: ғинуар, февраль, март, апрель, май, июнь, июль, август, сентябрь,\nоктябрь, ноябрь, декабрь.\nТыуған көн тураһындағы яуап — шәхси.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":18,"key":"9-18","label":"Бүлек 9 · №18","question":"Ориентир по заголовку блока ответов: Текстың дөрөҫ тәртибе:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Текстың дөрөҫ тәртибе:\nБалалар лагерҙа ял итәләр.\nЛагерь Дим буйында урынлашҡан.\nУл район үҙәгенән алыҫ түгел.\nЛагерҙан Ҡыҙылъяр ауылы күренеп тора.\n\nИкенсе өлөш:\nБеренсе отрядта — 7-се класс уҡыусылары.\nУлар тиҙ дуҫлашты.\nБер ваҡыт балалар урманға еләккә китте.\nЮлда ҡапыл Айраттың аяғын йылан саҡты.\nШул саҡ Фәриҙә башындағы яулығын сисеп алып, Айраттың аяғын ҡыҫып бәйләп ҡуйҙы.\nШунан йыландың ағыуын ауыҙы менән һурып, ергә төкөрҙө.\nАйратты лагерға алып ҡайттылар.\nФәриҙә иптәшен шулай үлемдән ҡотҡарҙы.\n\n1) Өлгө: Эйе, мин дә бәләгә тарыған кешегә өлкәндәрҙе саҡырып,\nашығыс ярҙам күрһәтергә тырышыр инем.\n2) Дим йылғаһының ҡайҙан башланыуы был әҙәби текстта әйтелмәй;\nгеография картаһы/өҫтәмә сығанаҡ кәрәк.\n3) Мәҡәлдәр:\n«Дуҫ бәлә килгәндә һынала».\n«Дуҫтың дуҫлығы яуҙа беленә».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":19,"key":"9-19","label":"Бүлек 9 · №19","question":"Ориентир по заголовку блока ответов: Сит ил уҡыусыһына электрон хат — өлгө:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Сит ил уҡыусыһына электрон хат — өлгө:\n«Сәләм! Мин Башҡортостанда йәшәйем һәм 7-се класта уҡыйым.\nМинең мәктәбемдә дуҫтарым күп. Буш ваҡытта спорт менән шөғөлләнәм,\nмузыка тыңлайым һәм китап уҡыйым. Башҡортостанда төрлө халыҡтар\nтатыу йәшәй. Һиңә лә үҙ мәктәбең һәм ҡалаң тураһында яҙырға тәҡдим итәм».","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":20,"key":"9-20","label":"Бүлек 9 · №20","question":"Ориентир по заголовку блока ответов: Китапты ремонтлау тураһында диалог:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Китапты ремонтлау тураһында диалог:\n— Был китаптың тышы йыртылған.\n— Әйҙә, уны йәбештерәйек.\n— Мин елем һәм ҡағыҙ алып киләм.\n— Ә мин биттәрен тигеҙләп ҡуям.\n— Китапты һаҡлап тоторға кәрәк.\n— Эйе, китап — беҙҙең дуҫыбыҙ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":21,"key":"9-21","label":"Бүлек 9 · №21","question":"Ориентир по заголовку блока ответов: А. С. Пушкиндың бала сағы:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"А. С. Пушкиндың бала сағы:\nПушкин бала саҡтан уҡ китап уҡырға бик яратҡан.\nУл атаһының китап шкафынан китаптар алып, хатта төндә лә уҡыған.\nКарамзин кеүек яҙыусыларҙың һөйләшеүҙәрен тыңлаған.\nУн бер йәшенә француз әҙәбиәтен яҡшы белгән.\nТөп фекер: буласаҡ шағирҙың әҙәбиәткә ҡыҙыҡһыныуы бик иртә уянған.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":22,"key":"9-22","label":"Бүлек 9 · №22","question":"Ориентир по заголовку блока ответов: Йомаҡтар:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Йомаҡтар:\n1) тауыҡ;\n2) әтәс;\n3) тумыртҡа;\n4) ҡарға;\n5) турғай;\n6) һандуғас.\n\nЫмлыҡ/тауыш оҡшатыуҙар:\nҡыт-ҡытыҡ, кикирикүүүк, туҡ-та-туҡ, сирыҡ-сирыҡ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":23,"key":"9-23","label":"Бүлек 9 · №23","question":"Ориентир по заголовку блока ответов: 1) Эт, бесәй, ат, һыйыр, ҡаҙ, өйрәк — йорт хайуандары/ҡоштары.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"1) Эт, бесәй, ат, һыйыр, ҡаҙ, өйрәк — йорт хайуандары/ҡоштары.\n2) Әтәс — «кикирикүүүк», тауыҡ — «ҡыт-ҡытыҡ» тип ҡысҡыра;\nкүркә һәм башҡа ҡоштарҙың тауыш оҡшатыуҙары һөйләшкә ҡарап төрлөсә әйтелергә мөмкин.\n3) Хайуандарҙы саҡырыу/ҡыуыу һүҙҙәре төбәктәргә ҡарап айырыла.\nУчебникта уларҙың берҙәм әҙер исемлеге бирелмәгән, шуға был өлөштө\nуҡытыусы ҡулланған урындағы вариант менән тултырыу дөрөҫ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":24,"key":"9-24","label":"Бүлек 9 · №24","question":"Ориентир по заголовку блока ответов: Кроссворд өсөн тәржемәләр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Кроссворд өсөн тәржемәләр:\nзаяц — ҡуян;\nёжик — терпе;\nлось — мышы;\nмедведь — айыу;\nлиса — төлкө;\nгалка — сәүкә;\nдятел — тумыртҡа;\nолень — болан.\nҮҙәк һүҙ: ТЫНЫСЛЫҠ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":25,"key":"9-25","label":"Бүлек 9 · №25","question":"Ориентир по заголовку блока ответов: Ҡоштар:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Ҡоштар:\nласточка — ҡарлуғас;\nсоловей — һандуғас;\nжаворонок — һабан турғайы;\nграч — ҡара ҡарға;\nкукушка — кәкүк;\nлебедь — аҡҡош.\n\nӨлгө һөйләү:\nҺандуғас — бәләкәй генә йырсы ҡош. Ул матур тауышы менән билдәле.\nЙәйен урман һәм ҡыуаҡлыҡтарҙа йәшәй, бөжәктәр менән туҡлана.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":26,"key":"9-26","label":"Бүлек 9 · №26","question":"Ориентир по заголовку блока ответов: Дөрөҫ яраштырыу:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Дөрөҫ яраштырыу:\n1) Сыйырсыҡтар килгәнсе үк, иҫке ояларын төҙәтеп, яңыларын яһап,\nағастарға, ҡыйыҡтарға ҡуйырға кәрәк.\n2) Улар бөжәктәрҙе ашайҙар.\n3) Ҡоштар — беҙҙең ҡанатлы дуҫтарыбыҙ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":27,"key":"9-27","label":"Бүлек 9 · №27","question":"Ориентир по заголовку блока ответов: Проект «Ҡоштар — беҙҙең дуҫтарыбыҙ»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Проект «Ҡоштар — беҙҙең дуҫтарыбыҙ»:\n1) Беҙҙең яҡ ҡоштары.\n2) Күсмә һәм ҡышлаусы ҡоштар.\n3) Ҡоштарҙың тәбиғәттәге файҙаһы.\n4) Оя һәм тағараҡ яһау.\n5) Ҡоштарҙы һаҡлау ҡағиҙәләре.\n6) Йомғаҡ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":28,"key":"9-28","label":"Бүлек 9 · №28","question":"Ориентир по заголовку блока ответов: Һүҙлек диктанты — һүҙҙәрҙе яҙылышы менән әҙерләү.","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һүҙлек диктанты — һүҙҙәрҙе яҙылышы менән әҙерләү.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":29,"key":"9-29","label":"Бүлек 9 · №29","question":"Ориентир по заголовку блока ответов: Башватҡыс:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Башватҡыс:\nАсҡысы — башҡорт алфавиты.\n8,4 / 8,26,14,8,34,8,4,40 / 8,26,17,8,34 / 26,21,23,16,21 /\n31,21,18,40,23 / 7,40 / 1,7\n\nЯуап:\n«ЕГЕТ КЕШЕГӘ ЕТМЕШ ТӨРЛӨ ҺӨНӘР ҘӘ АҘ».\n\nМәғәнәһе: кеше күп һөнәр белһә лә, файҙалы белем һәм оҫталыҡ артыҡ булмай.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]}]},{"title":"Бүлек 10. ЙӘМЛЕ ЙӘЙ","tasks":[{"number":1,"key":"10-1","label":"Бүлек 10 · №1","question":"Ориентир по заголовку блока ответов: Һөйләм төрҙәре:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һөйләм төрҙәре:\n1) Һөйләмдә эш йәки ваҡиға тураһында хәбәр ителһә, аҙағына нөктә ҡуйыла.\n2) Һөйләмдә берәй нәмә тураһында һоралһа, һорау билдәһе ҡуйыла.\n3) Көслө тойғо, ғәжәпләнеү йәки саҡырыу булһа, өндәү билдәһе ҡуйыла.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":2,"key":"10-2","label":"Бүлек 10 · №2","question":"Ориентир по заголовку блока ответов: Йәй тураһында:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Йәй тураһында:\nЙәйен көндәр оҙон һәм йылы була. Ағастар йәшелләнә, сәскәләр ата,\nеләк-емеш өлгөрә. Балалар каникулға сыға, һыу инә, сәйәхәт итә һәм ял итә.\nМин йәйҙе йылы һауаһы һәм тәбиғәттең матурлығы өсөн яратам.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":3,"key":"10-3","label":"Бүлек 10 · №3","question":"Ориентир по заголовку блока ответов: Ҡылымдар:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Ҡылымдар:\nкилеп етте — үткән заман, 3-сө зат, берлек;\nтамамланы — үткән заман, 3-сө зат (контекстта күплек эйәһе менән);\nоҙатты — үткән заман, 3-сө зат, берлек;\nкилерҙәр — киләсәк заман, 3-сө зат, күплек.\nБашҡа ҡылымдарҙы ла шул уҡ принцип буйынса билдәләргә.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":4,"key":"10-4","label":"Бүлек 10 · №4","question":"Ориентир по заголовку блока ответов: Һөйләмдәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һөйләмдәр:\nХәбәр: Июнь айынан йәй башлана.\nҺорау: Июнь айынан йәй башланамы?\nӨндәү: Йәмле йәй, тиҙерәк кил!\n\nХәбәр: Юл буйында юл япрағы үҫә.\nҺорау: Юл буйында юл япрағы үҫәме?\nӨндәү: Ҡарағыҙ, юл буйында юл япрағы үҫә!","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":5,"key":"10-5","label":"Бүлек 10 · №5","question":"Ориентир по заголовку блока ответов: Ямғыр тураһында:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Ямғыр тураһында:\n1) Ятлау — устно.\n2) Өлгө: Ямғыр яуғанда мин сафлыҡ һәм шатлыҡ тойғоһо кисерәм.\n3) Ямғыр үҫемлектәргә һәм тупраҡҡа дым бирә, йылғалар һәм күлдәрҙе тулыландыра.\n4) «Яңы күлдәк кейер алда...» образы: ямғыр ерҙе йыуып таҙарта,\nшунан тәбиғәт йәшел «яңы күлдәк» кейгәндәй була.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":6,"key":"10-6","label":"Бүлек 10 · №6","question":"Ориентир по заголовку блока ответов: Сәскәләр сере тураһында:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Сәскәләр сере тураһында:\nТекстың грамматик маҡсаты — йәйә эсендәге ялғауҙарҙы һүҙҙең мәғәнәһенә\nһәм һөйләмдәге бәйләнешенә ҡарап һайлау.\nТөп мәғәнә: сәскәләрҙең ҡайһы берҙәре таж япраҡтарын асыу/ябыу һәм\nбашҡа үҙгәрештәр менән һауа торошон йәки ваҡытты «күрһәтә» ала.\nӨлгө: ямғыр алдынан ҡайһы бер сәскәләр таж япраҡтарын ябып ҡуя.\n1) Өҫтәмә сәскә сере: көнбағыш көн дауамында яҡтылыҡҡа табан борола.\n2) Һүрәт төшөрөү — ижади эш.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":7,"key":"10-7","label":"Бүлек 10 · №7","question":"Ориентир по заголовку блока ответов: «Розалия»:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Розалия»:\nУҡыуҙар бөттө, йәй килеп етте.\nБер көн иртәнсәк Розалияның әсәһе эшкә китеп барғанда,\nҡулына портфель тотоп барған Хәлиҙәне осрата.\n— Ниңә улай каникул көнө мәктәпкә бараһың? — тип һорай ул.\n— Имтихан/уҡыу эше бар, — тип яуапланы Хәлиҙә.\nРозалия йоҡлай әле ул, йәй бит.\n— Эй ялҡау, — тип уйланы күрше ҡыҙы.\n\nКем ялҡау?\nТекстта Хәлиҙә Розалияны ялҡау тип атай, ләкин каникул ваҡытында иртән\nоҙағыраҡ йоҡлау үҙе генә ялҡаулыҡты иҫбат итмәй. Был — юморлы хәл.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":8,"key":"10-8","label":"Бүлек 10 · №8","question":"Ориентир по заголовку блока ответов: Диалогтар:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Диалогтар:\n1)\n— Дамир, мин һинең менән хушлашырға индем. Йәйге каникулда ауылға китәм.\n— Күпмегә?\n— Бер айға.\n— Яҡшы ял ит! Ҡайтҡас осрашырбыҙ.\n— Рәхмәт, һау бул!\n\n2)\n— Уҡыусылар, йәй көндәрендә коллекциялар, гербарийҙар йыйығыҙ.\n— Ниндәй үҫемлектәрҙе йыйырға мөмкин?\n— Ҡыҙыл китапҡа инмәгән, күп таралған үҫемлектәрҙе генә.\n— Уларҙы нисек киптерергә?\n— Ҡағыҙ араһына һалып, һаҡ ҡына киптерегеҙ.\n\n3)\n— Урал, походҡа сәғәт 10-да китәбеҙ, һуңлама.\n— Ярай. Үҙем менән нимә алайым?\n— Һыу, еңел аҙыҡ, ямғырҙан һаҡланыр кейем ал.\n— Килештек.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":9,"key":"10-9","label":"Бүлек 10 · №9","question":"Ориентир по заголовку блока ответов: Шиғыр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Шиғыр:\n1) Йәй миҙгеле һүрәтләнгән. Быны йылы көндәр, йәшеллек, сәскәләр,\nямғыр/ысыҡ һәм йәйге тәбиғәт күренештәре күрһәтә.\n2) Ятлау — устно.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":10,"key":"10-10","label":"Бүлек 10 · №10","question":"Ориентир по заголовку блока ответов: «Ҡырмыҫҡалар».","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Ҡырмыҫҡалар».\nНи өсөн шулай атала?\nБөтә текст ҡырмыҫҡаларҙың тормошо, файҙаһы, үҙ-ара ярҙамы һәм «аралашыуы»\nтураһында, шуға исем тап килә.\nБашҡа исем: «Урман санитарҙары» йәки «Ысын дуҫлыҡ».\n\n1) Рауил ҡырмыҫҡа иләүен таяҡ менән бутарға йыйына.\n2) Ғәлләм ағай ҡырмыҫҡаларҙың зарарлы бөжәктәрҙе юҡ итеүен, тупраҡты\nйомшартыуын, ашлама индереүен, бер-береһен дауалауын һәм ишаралар менән\nаралашыуын белә.\n3) Бер иләү йәй эсендә дүрт-биш миллион бөжәкте юҡ итә.\n4) «Хирург» ҡырмыҫҡалар ауырыу ҡырмыҫҡа янына килеп, морондары һәм аяҡтары\nменән ярҙам итә; текста улар уны ҡыҫылған юнысҡынан ҡотҡара.\n5) Ҡырмыҫҡа саҡ күтәрелеп, ауыҙын асһа — «иғтибар итегеҙ»;\nиптәшенең башына өҫтән аҫҡа һуҡһа — «тревога».\n6) Канау аша ҡырмыҫҡалар аяҡтары һәм ауыҙҙары менән бер-береһенә тотоноп\n«тере күпер» яһаған. Өс тәүлек буйына башҡа ҡырмыҫҡалар шул күперҙән йөк ташыған.\n7) Ҡырмыҫҡалар файҙалы, ойошҡан, бер-береһенә ярҙам итә һәм урмандың\nтаҙалығына булышлыҡ итә.\n8) План:\n1. Рауилдың ҡырмыҫҡа иләүенә тейеүе.\n2. Ғәлләм ағайҙың аңлатыуы.\n3. Ҡырмыҫҡа «хирургтары».\n4. Ҡырмыҫҡаларҙың сигналдары.\n5. «Тере күпер».\n6. Дуҫлыҡ һәм иптәшлек.\n9) План буйынса һөйләү — алдағы яуаптарҙы ҡулланығыҙ.\n10) Урманда сүп ташламаҫҡа, ҡырмыҫҡа иләүҙәрен боҙмаҫҡа, ағас һәм үҫемлектәрҙе\nзарарламаҫҡа, усаҡ менән һаҡ булырға, йәнлектәрҙе борсомаҫҡа кәрәк.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":11,"key":"10-11","label":"Бүлек 10 · №11","question":"Ориентир по заголовку блока ответов: I. Һүҙҙәр ике бағанаға һуҙынҡы өндәрҙең ҡалын/нәҙек һәм мәғәнә айырмаһын","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"I. Һүҙҙәр ике бағанаға һуҙынҡы өндәрҙең ҡалын/нәҙек һәм мәғәнә айырмаһын\nкүрһәткән өсөн яҙылған:\nҡорт — көрт;\nһоло — һөлөк;\nборос — бөрө;\nбойор — бөйөр;\nбойоҡ — бөйөк.\nҺығымта: башҡорт телендә һуҙынҡы өндө дөрөҫ әйтеү һүҙҙең мәғәнәһен үҙгәртә ала.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":12,"key":"10-12","label":"Бүлек 10 · №12","question":"Ориентир по заголовку блока ответов: Тыуған ер тураһында:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Тыуған ер тураһында:\nТөп фекер — кеше тыуған ҡалаһын/ауылын, тәбиғәтен, кешеләрен ярата һәм һаҡларға тейеш.\nӨлгө:\nМинең тыуған ҡалам/ауылым матур. Унда мәктәптәр, урамдар, парктар һәм\nтәбиғәт урындары бар. Мин тыуған ерем менән ғорурланам һәм уны таҙа тотоуҙы\nүҙемдең бурысым тип иҫәпләйем.\n2) Һөйләм баш киҫәктәрен текстта уҡыусы үҙе һыҙа: эйә + хәбәр.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":13,"key":"10-13","label":"Бүлек 10 · №13","question":"Ориентир по заголовку блока ответов: Һүрәт буйынса:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Һүрәт буйынса:\nӨлгө: Ҡыҙ урманда матур сәскә йәки үҫемлек осрата. Ул уны өҙөр алдынан\nбыл үҫемлектең һирәк булыу-булмауын уйларға тейеш. Әгәр сәскә Ҡыҙыл китапҡа\nинһә, уға тейергә ярамай. Тәбиғәттең матурлығын фотоға төшөрөп һаҡлау яҡшыраҡ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":14,"key":"10-14","label":"Бүлек 10 · №14","question":"Ориентир по заголовку блока ответов: Диалогтар:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Диалогтар:\n1)\n— Ҡарағыҙ әле, был аҡланда күпме матур сәскә үҫә!\n— Әйҙә, ҙур гөлләмә йыяйыҡ.\n— Юҡ, бөтәһен дә өҙөргә ярамай. Сәскәләр тәбиғәттә үҫһен.\n— Дөрөҫ, бер нисәүһен дә өҙмәй, фотоға төшөрәйек.\n\n2)\n— Хәлиҙә, әйҙә, кем күберәк сәскә йыйыр икән!\n— Улай ярышырға ярамай. Беҙ күп сәскәне юҡ итербеҙ.\n— Ә нимә эшләйек?\n— Һирәк үҫемлектәрҙе күҙәтәйек, һүрәткә төшөрәйек, ә өҙмәйек.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":15,"key":"10-15","label":"Бүлек 10 · №15","question":"Ориентир по заголовку блока ответов: «Самое важное» тексының башҡортса мәғәнәһе:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"«Самое важное» тексының башҡортса мәғәнәһе:\nКеше үҙенең тышҡы ҡиәфәтен тулыһынса һайлай алмай, ләкин характерын тәрбиәләй ала.\nНыҡышмаллыҡ, эште аҙағына тиклем еткереү, изгелек, яуаплылыҡ һәм үҙ-үҙең өҫтөндә\nэшләү — кешенең иң мөһим сифаттары.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":16,"key":"10-16","label":"Бүлек 10 · №16","question":"Ориентир по заголовку блока ответов: Тема буйынса һүҙҙәр:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Тема буйынса һүҙҙәр:\nйәй, каникул, ҡояш, ямғыр, сәскә, урман, йылға, лагерь, поход, ял,\nгербарий, тәбиғәт, ҡырмыҫҡа, болон, еләк, йәшеллек.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]},{"number":17,"key":"10-17","label":"Бүлек 10 · №17","question":"Ориентир по заголовку блока ответов: Йәйге иртә:","summaryOnly":false,"answerPending":false,"rule":"Формулировка темы дана по заголовку блока в пользовательском файле ответов; это не дословный текст задания из учебника.","answer":"Йәйге иртә:\n1) Бер строфаны ятлау — устно.\n2) Шағир йәйге иртәнең сафлығына, яҡтылығына һәм тәбиғәттең уяныуына һоҡлана.\n3) Өлгө: Эйе, лагерҙа ял иткәнем бар. Иртән саф һауала зарядка яһайбыҙ,\nашайбыҙ, спорт уйнайбыҙ, походҡа сығабыҙ һәм төрлө сараларҙа ҡатнашабыҙ.","steps":["Сверили номер задания с разделом.","Перенесли полный ответ из предоставленного файла без сокращений."]}]}];
})();
